     1→use crate::data::{NodeKind, EdgeKind, SpecRepository, SpecNodeData};
     2→use std::collections::HashMap;
     3→use std::path::Path;
     4→
     5→/// Specification inferred from source code analysis
     6→#[derive(Debug, Clone)]
     7→pub struct InferredSpecification {
     8→    pub content: String,
     9→    pub kind: NodeKind,
    10→    pub confidence: f32,      // 0.0-1.0
    11→    pub source_file: String,
    12→    pub source_line: usize,
    13→    pub formality_layer: u8,  // 0=natural, 1=structured, 2=formal, 3=executable
    14→    pub metadata: HashMap<String, String>,
    15→}
    16→
    17→/// Result of ingesting inferred specifications into graph
    18→#[derive(Debug)]
    19→pub struct IngestionReport {
    20→    pub nodes_created: usize,
    21→    pub nodes_skipped: usize,
    22→    pub edges_created: usize,
    23→    pub suggestions: Vec<EdgeSuggestion>,
    24→    pub contradictions_found: Vec<String>,
    25→}
    26→
    27→/// Suggested edge that needs human review
    28→#[derive(Debug)]
    29→pub struct EdgeSuggestion {
    30→    pub source_id: String,
    31→    pub target_id: String,
    32→    pub kind: EdgeKind,
    33→    pub confidence: f32,
    34→    pub explanation: String,
    35→}
    36→
    37→impl SpecRepository {
    38→    /// Check if inferred spec has sufficient semantic quality
    39→    fn is_high_quality_spec(spec: &InferredSpecification) -> bool {
    40→        let content = &spec.content;
    41→
    42→        // Skip low-quality test assertions that are just code artifacts
    43→        // Examples: "Invariant: g.node_count(), 1", "Invariant: fetched.kind, NodeKind::Assertion"
    44→        if content.starts_with("Invariant: ") {
    45→            // Reject if it contains Rust syntax (it's code, not a spec)
    46→            let rust_syntax_markers = [
    47→                ".iter()", ".any(", ".contains(", ".len()", ".get(",
    48→                "!(", "||", "&&", ">", "<", "==", "!=",
    49→                ".is_empty()", ".starts_with(", ".ends_with(",
    50→                "assert!", "panic!", "unwrap(", "expect(",
    51→                "{}", "[]", "\"{}\"", "format!", "println!"
    52→            ];
    53→            let has_rust_syntax = rust_syntax_markers.iter()
    54→                .any(|marker| content.contains(marker));
    55→
    56→            if has_rust_syntax {
    57→                return false;  // Rust code, not a specification
    58→            }
    59→
    60→            // Also check for semantic keywords (original filter)
    61→            let semantic_keywords = [
    62→                "must", "should", "shall", "require", "ensure", "verify", "validate",
    63→                "detect", "identify", "check", "test verifies", "system", "user",
    64→                "specification", "requirement", "constraint"
    65→            ];
    66→
    67→            let has_semantic_meaning = semantic_keywords.iter()
    68→                .any(|kw| content.to_lowercase().contains(kw));
    69→
    70→            if !has_semantic_meaning {
    71→                // Low-quality test assertion - skip it
    72→                return false;
    73→            }
    74→        }
    75→
    76→        // Skip trivial scenario names that provide no information
    77→        // Examples: "scenario {}", "coverage empty graph", "coverage no tests"
    78→        if content == "scenario {}" || content.trim().is_empty() {
    79→            return false;
    80→        }
    81→
    82→        // Skip test function names that are too short or lack strong semantic value
    83→        // Examples: "coverage empty graph", "empty graph", "no tests", "user login"
    84→        if spec.kind == NodeKind::Scenario || spec.metadata.get("extractor") == Some(&"function_name".to_string()) {
    85→            // Check minimum length (at least 25 characters for descriptive spec)
    86→            if content.len() < 25 {
    87→                return false;
    88→            }
    89→
    90→            // Must have strong semantic keywords (not just "user" or "test")
    91→            let strong_keywords = [
    92→                "must", "should", "shall", "ensure", "verify", "validate",
    93→                "detect", "identify", "check for", "when", "if",
    94→                "specification", "requirement", "constraint", "correctly", "properly",
    95→                "without", "with", "given", "then", "returns", "accepts"
    96→            ];
    97→            let has_strong_semantic = strong_keywords.iter()
    98→                .any(|kw| content.to_lowercase().contains(kw));
    99→
   100→            // Reject if no strong semantics OR if it's just a test name pattern
   101→            let is_trivial_test_name = content.to_lowercase().starts_with("scenario: ") &&
   102→                !has_strong_semantic;
   103→
   104→            if !has_strong_semantic || is_trivial_test_name {
   105→                return false;
   106→            }
   107→        }
   108→
   109→        true
   110→    }
   111→
   112→    /// Ingest inferred specifications into the graph
   113→    pub fn ingest(&mut self, specs: Vec<InferredSpecification>) -> IngestionReport {
   114→        let mut report = IngestionReport {
   115→            nodes_created: 0,
   116→            nodes_skipped: 0,
   117→            edges_created: 0,
   118→            suggestions: Vec::new(),
   119→            contradictions_found: Vec::new(),
   120→        };
   121→
   122→        // Create nodes for high-confidence inferences (with deduplication)
   123→        let mut created_ids = Vec::new();
   124→        for spec in specs {
   125→            // Apply both confidence threshold and quality filter
   126→            if spec.confidence >= 0.7 && Self::is_high_quality_spec(&spec) {
   127→                // Check for duplicate before creating node
   128→                if let Some(existing) = self.find_node_by_content(&spec.content, spec.kind) {
   129→                    // Duplicate found - skip creation, but track for edge inference
   130→                    created_ids.push(existing.id.clone());
   131→                    report.nodes_skipped += 1;
   132→                } else {
   133→                    // New node - create it
   134→                    let mut metadata = spec.metadata.clone();
   135→                    metadata.insert("source_file".to_string(), spec.source_file.clone());
   136→                    metadata.insert("source_line".to_string(), spec.source_line.to_string());
   137→                    metadata.insert("confidence".to_string(), spec.confidence.to_string());
   138→                    metadata.insert("inferred".to_string(), "true".to_string());
   139→
   140→                    let node = self.add_node_with_layer(
   141→                        spec.content,
   142→                        spec.kind,
   143→                        spec.formality_layer,
   144→                        metadata,
   145→                    );
   146→                    created_ids.push(node.id.clone());
   147→                    report.nodes_created += 1;
   148→                }
   149→            } else {
   150→                report.nodes_skipped += 1;
   151→            }
   152→        }
   153→
   154→        // Infer relationships between newly created nodes and existing nodes
   155→        for node_id in &created_ids {
   156→            let suggestions = self.infer_relationships_for_node(node_id);
   157→
   158→            for suggestion in suggestions {
   159→                if suggestion.confidence >= 0.8 {
   160→                    // High confidence: auto-create edge
   161→                    if self.add_edge(
   162→                        &suggestion.source_id,
   163→                        &suggestion.target_id,
   164→                        suggestion.kind,
   165→                        HashMap::new(),
   166→                    ).is_ok() {
   167→                        report.edges_created += 1;
   168→                    }
   169→                    // Ignore errors (node might not exist)
   170→                } else if suggestion.confidence >= 0.5 {
   171→                    // Medium confidence: suggest for human review
   172→                    report.suggestions.push(suggestion);
   173→                }
   174→            }
   175→        }
   176→
   177→        // TODO: Contradiction detection should be done via UDAFModel.detect_contradictions()
   178→        // This is a formal verification operation, not a data layer operation.
   179→        // For now, we skip contradiction detection during ingestion.
   180→        // It will be done separately via the formal layer.
   181→
   182→        report
   183→    }
   184→
   185→    /// Add node with explicit formality layer
   186→    pub fn add_node_with_layer(
   187→        &mut self,
   188→        content: String,
   189→        kind: NodeKind,
   190→        formality_layer: u8,
   191→        metadata: HashMap<String, String>,
   192→    ) -> SpecNodeData {
   193→        // Use existing add_node infrastructure
   194→        let node = self.add_node(content, kind, metadata);
   195→        let node_id = node.id.clone();
   196→
   197→        // Update formality layer
   198→        self.update_node_formality(&node_id, formality_layer);
   199→
   200→        // Return updated node
   201→        self.get_node(&node_id).unwrap().clone()
   202→    }
   203→
   204→    /// Infer relationships for all nodes in the graph
   205→    pub fn infer_all_relationships(&mut self) -> IngestionReport {
   206→        let mut report = IngestionReport {
   207→            nodes_created: 0,
   208→            nodes_skipped: 0,
   209→            edges_created: 0,
   210→            suggestions: Vec::new(),
   211→            contradictions_found: Vec::new(),
   212→        };
   213→
   214→        // Get all node IDs
   215→        let all_ids: Vec<String> = self.list_nodes(None).iter().map(|n| n.id.clone()).collect();
   216→
   217→        // Infer relationships for each node
   218→        for node_id in &all_ids {
   219→            let suggestions = self.infer_relationships_for_node(node_id);
   220→
   221→            for suggestion in suggestions {
   222→                if suggestion.confidence >= 0.8 {
   223→                    // High confidence: auto-create edge
   224→                    if self.add_edge(
   225→                        &suggestion.source_id,
   226→                        &suggestion.target_id,
   227→                        suggestion.kind,
   228→                        HashMap::new(),
   229→                    ).is_ok() {
   230→                        report.edges_created += 1;
   231→                    }
   232→                    // Ignore errors (edge might already exist)
   233→                } else if suggestion.confidence >= 0.5 {
   234→                    // Medium confidence: suggest for human review
   235→                    report.suggestions.push(suggestion);
   236→                }
   237→            }
   238→        }
   239→
   240→        report
   241→    }
   242→
   243→    /// Automatically infer and create relationships for a single newly-added node
   244→    /// This enables automatic re-integration when specs are added manually
   245→    pub fn auto_connect_node(&mut self, node_id: &str) -> IngestionReport {
   246→        let mut report = IngestionReport {
   247→            nodes_created: 0,
   248→            nodes_skipped: 0,
   249→            edges_created: 0,
   250→            suggestions: Vec::new(),
   251→            contradictions_found: Vec::new(),
   252→        };
   253→
   254→        // Infer relationships for the specified node
   255→        let suggestions = self.infer_relationships_for_node(node_id);
   256→
   257→        for suggestion in suggestions {
   258→            if suggestion.confidence >= 0.8 {
   259→                // High confidence: auto-create edge
   260→                if self.add_edge(
   261→                    &suggestion.source_id,
   262→                    &suggestion.target_id,
   263→                    suggestion.kind,
   264→                    HashMap::new(),
   265→                ).is_ok() {
   266→                    report.edges_created += 1;
   267→                }
   268→                // Ignore errors (edge might already exist)
   269→            } else if suggestion.confidence >= 0.5 {
   270→                // Medium confidence: suggest for human review
   271→                report.suggestions.push(suggestion);
   272→            }
   273→        }
   274→
   275→        report
   276→    }
   277→
   278→    /// Infer relationships with AI enhancement for cross-layer semantic matching (optimized)
   279→    /// Only compares nodes across different formality layers to create Formalizes edges
   280→    pub fn infer_cross_layer_relationships_with_ai(&mut self, min_confidence: f32) -> IngestionReport {
   281→        let mut report = IngestionReport {
   282→            nodes_created: 0,
   283→            nodes_skipped: 0,
   284→            edges_created: 0,
   285→            suggestions: Vec::new(),
   286→            contradictions_found: Vec::new(),
   287→        };
   288→
   289→        // Initialize AI engine
   290→        let ai = crate::AISemantic::default();
   291→        if !ai.is_available() {
   292→            eprintln!("Warning: AI command not available");
   293→            return report;
   294→        }
   295→
   296→        println!("Using AI-enhanced semantic matching for cross-layer relationships...");
   297→
   298→        // Group nodes by formality layer
   299→        let all_nodes = self.list_nodes(None);
   300→        let mut layers: HashMap<u8, Vec<crate::SpecNodeData>> = HashMap::new();
   301→        for node in all_nodes {
   302→            layers.entry(node.formality_layer).or_default().push(node.clone());
   303→        }
   304→
   305→        let layer_keys: Vec<u8> = layers.keys().copied().collect();
   306→        println!("  Found layers: {:?}", layer_keys);
   307→
   308→        // Only compare across layers (source_layer < target_layer for Formalizes)
   309→        let mut total_comparisons = 0;
   310→        for source_layer in &layer_keys {
   311→            for target_layer in &layer_keys {
   312→                if source_layer >= target_layer {
   313→                    continue; // Skip same-layer and reverse comparisons
   314→                }
   315→
   316→                let source_nodes = layers.get(source_layer).unwrap();
   317→                let target_nodes = layers.get(target_layer).unwrap();
   318→                let comparisons = source_nodes.len() * target_nodes.len();
   319→                total_comparisons += comparisons;
   320→
   321→                println!("  Comparing layer {} -> {} ({} × {} = {} pairs)",
   322→                    source_layer, target_layer,
   323→                    source_nodes.len(), target_nodes.len(), comparisons);
   324→
   325→                for (i, source_node) in source_nodes.iter().enumerate() {
   326→                    if i % 10 == 0 && i > 0 {
   327→                        println!("    Progress: {}/{} layer {} nodes", i, source_nodes.len(), source_layer);
   328→                    }
   329→
   330→                    for target_node in target_nodes {
   331→                        let similarity = self.calculate_semantic_similarity_with_ai(
   332→                            &source_node.content,
   333→                            source_node.formality_layer,
   334→                            &target_node.content,
   335→                            target_node.formality_layer,
   336→                            &ai,
   337→                        );
   338→
   339→                        if similarity < 0.5 {
   340→                            continue; // Not similar enough for Formalizes
   341→                        }
   342→
   343→                        // Create Formalizes edge suggestion
   344→                        let confidence = similarity * 0.9;
   345→                        let suggestion = EdgeSuggestion {
   346→                            source_id: source_node.id.clone(),
   347→                            target_id: target_node.id.clone(),
   348→                            kind: EdgeKind::Formalizes,
   349→                            confidence,
   350→                            explanation: format!(
   351→                                "Same concept at different formality levels ({} -> {})",
   352→                                source_layer, target_layer
   353→                            ),
   354→                        };
   355→
   356→                        if confidence >= min_confidence {
   357→                            if self.add_edge(
   358→                                &suggestion.source_id,
   359→                                &suggestion.target_id,
   360→                                suggestion.kind,
   361→                                HashMap::new(),
   362→                            ).is_ok() {
   363→                                report.edges_created += 1;
   364→                            }
   365→                            // Edge might already exist
   366→                        } else if confidence >= 0.5 {
   367→                            report.suggestions.push(suggestion);
   368→                        }
   369→                    }
   370→                }
   371→            }
   372→        }
   373→
   374→        let (cache_size, _) = ai.cache_stats();
   375→        println!("  Total comparisons: {}", total_comparisons);
   376→        println!("  AI cache size: {} entries", cache_size);
   377→        println!("  Formalizes edges created: {}", report.edges_created);
   378→
   379→        report
   380→    }
   381→
   382→    /// Infer relationships with AI enhancement for cross-layer semantic matching
   383→    pub fn infer_all_relationships_with_ai(&mut self, min_confidence: f32) -> IngestionReport {
   384→        let mut report = IngestionReport {
   385→            nodes_created: 0,
   386→            nodes_skipped: 0,
   387→            edges_created: 0,
   388→            suggestions: Vec::new(),
   389→            contradictions_found: Vec::new(),
   390→        };
   391→
   392→        // Get all node IDs
   393→        let all_ids: Vec<String> = self.list_nodes(None).iter().map(|n| n.id.clone()).collect();
   394→
   395→        // Initialize AI engine
   396→        let ai = crate::AISemantic::default();
   397→        if !ai.is_available() {
   398→            eprintln!("Warning: AI command not available, falling back to simple inference");
   399→            return self.infer_all_relationships();
   400→        }
   401→
   402→        println!("Using AI-enhanced semantic matching for cross-layer relationships...");
   403→
   404→        // Infer relationships for each node
   405→        for (i, node_id) in all_ids.iter().enumerate() {
   406→            if i % 50 == 0 {
   407→                println!("  Progress: {}/{} nodes processed", i, all_ids.len());
   408→            }
   409→
   410→            let suggestions = self.infer_relationships_for_node_with_ai(node_id, &ai);
   411→
   412→            for suggestion in suggestions {
   413→                if suggestion.confidence >= min_confidence {
   414→                    // High confidence: auto-create edge
   415→                    if self.add_edge(
   416→                        &suggestion.source_id,
   417→                        &suggestion.target_id,
   418→                        suggestion.kind,
   419→                        HashMap::new(),
   420→                    ).is_ok() {
   421→                        report.edges_created += 1;
   422→                    }
   423→                    // Ignore errors (edge might already exist)
   424→                } else if suggestion.confidence >= 0.5 {
   425→                    // Medium confidence: suggest for human review
   426→                    report.suggestions.push(suggestion);
   427→                }
   428→            }
   429→        }
   430→
   431→        let (cache_size, _) = ai.cache_stats();
   432→        println!("  AI cache size: {} entries", cache_size);
   433→
   434→        report
   435→    }
   436→
   437→    /// Infer relationships for a specific node with AI enhancement
   438→    fn infer_relationships_for_node_with_ai(&self, node_id: &str, ai: &crate::AISemantic) -> Vec<EdgeSuggestion> {
   439→        let mut suggestions = Vec::new();
   440→
   441→        let source_node = match self.get_node(node_id) {
   442→            Some(n) => n,
   443→            None => return suggestions,
   444→        };
   445→
   446→        // Get all other nodes
   447→        let all_nodes = self.list_nodes(None);
   448→
   449→        for target_node in all_nodes {
   450→            if target_node.id == node_id {
   451→                continue; // Skip self
   452→            }
   453→
   454→            // Calculate AI-enhanced semantic similarity
   455→            let similarity = self.calculate_semantic_similarity_with_ai(
   456→                &source_node.content,
   457→                source_node.formality_layer,
   458→                &target_node.content,
   459→                target_node.formality_layer,
   460→                ai,
   461→            );
   462→
   463→            // Layer-aware threshold: cross-layer connections need lower threshold
   464→            let threshold = if source_node.formality_layer != target_node.formality_layer {
   465→                0.15  // Cross-layer: proto↔requirement, test↔requirement
   466→            } else {
   467→                0.3   // Same-layer: more strict to avoid noise
   468→            };
   469→
   470→            if similarity < threshold {
   471→                continue; // Too dissimilar
   472→            }
   473→
   474→            // Infer edge kind and confidence based on multiple factors
   475→            if let Some((edge_kind, confidence, explanation)) =
   476→                self.infer_edge_kind(source_node, target_node, similarity)
   477→            {
   478→                suggestions.push(EdgeSuggestion {
   479→                    source_id: node_id.to_string(),
   480→                    target_id: target_node.id.clone(),
   481→                    kind: edge_kind,
   482→                    confidence,
   483→                    explanation,
   484→                });
   485→            }
   486→        }
   487→
   488→        suggestions
   489→    }
   490→
   491→    /// Infer relationships for a specific node
   492→    fn infer_relationships_for_node(&self, node_id: &str) -> Vec<EdgeSuggestion> {
   493→        let mut suggestions = Vec::new();
   494→
   495→        let source_node = match self.get_node(node_id) {
   496→            Some(n) => n,
   497→            None => return suggestions,
   498→        };
   499→
   500→        // Get all other nodes
   501→        let all_nodes = self.list_nodes(None);
   502→
   503→        for target_node in all_nodes {
   504→            if target_node.id == node_id {
   505→                continue; // Skip self
   506→            }
   507→
   508→            // Calculate semantic similarity
   509→            let similarity = self.calculate_semantic_similarity(
   510→                &source_node.content,
   511→                &target_node.content,
   512→            );
   513→
   514→            // Layer-aware threshold: cross-layer connections need lower threshold
   515→            // because proto/test specs are concise while requirements are detailed
   516→            let threshold = if source_node.formality_layer != target_node.formality_layer {
   517→                0.15  // Cross-layer: proto↔requirement, test↔requirement
   518→            } else {
   519→                0.3   // Same-layer: more strict to avoid noise
   520→            };
   521→
   522→            if similarity < threshold {
   523→                continue; // Too dissimilar
   524→            }
   525→
   526→            // Infer edge kind and confidence based on multiple factors
   527→            if let Some((edge_kind, confidence, explanation)) =
   528→                self.infer_edge_kind(source_node, target_node, similarity)
   529→            {
   530→                suggestions.push(EdgeSuggestion {
   531→                    source_id: node_id.to_string(),
   532→                    target_id: target_node.id.clone(),
   533→                    kind: edge_kind,
   534→                    confidence,
   535→                    explanation,
   536→                });
   537→            }
   538→        }
   539→
   540→        suggestions
   541→    }
   542→
   543→    /// Calculate semantic similarity between two texts (optionally AI-enhanced)
   544→    fn calculate_semantic_similarity(&self, text1: &str, text2: &str) -> f32 {
   545→        // Start with simple keyword-based similarity
   546→        let lower1 = text1.to_lowercase();
   547→        let lower2 = text2.to_lowercase();
   548→
   549→        let words1: std::collections::HashSet<String> =
   550→            lower1.split_whitespace().map(|s| s.to_string()).collect();
   551→        let words2: std::collections::HashSet<String> =
   552→            lower2.split_whitespace().map(|s| s.to_string()).collect();
   553→
   554→        if words1.is_empty() || words2.is_empty() {
   555→            return 0.0;
   556→        }
   557→
   558→        let intersection = words1.intersection(&words2).count();
   559→        let union = words1.union(&words2).count();
   560→
   561→        intersection as f32 / union as f32
   562→    }
   563→
   564→    /// Calculate semantic similarity with AI enhancement for cross-layer comparisons
   565→    fn calculate_semantic_similarity_with_ai(
   566→        &self,
   567→        text1: &str,
   568→        layer1: u8,
   569→        text2: &str,
   570→        layer2: u8,
   571→        ai: &crate::AISemantic,
   572→    ) -> f32 {
   573→        // First try simple similarity
   574→        let simple_sim = self.calculate_semantic_similarity(text1, text2);
   575→
   576→        // For cross-layer comparisons, ALWAYS use AI if available
   577→        // Keyword overlap is meaningless across layers (U0 uses natural language, U2/U3 use technical terms)
   578→        // Example: U0 "system must detect contradictions" ↔ U2 "RPC: DetectContradictions" (overlap ~0.1, semantic ~0.9)
   579→        if layer1 != layer2 {
   580→            if let Some(ai_sim) = ai.semantic_similarity(text1, text2, layer1, layer2) {
   581→                // Trust AI heavily for cross-layer matching
   582→                // Keyword overlap is noise, semantic equivalence is signal
   583→                return simple_sim * 0.2 + ai_sim * 0.8;
   584→            }
   585→            // AI unavailable: fall back to simple similarity (will miss many connections)
   586→            return simple_sim;
   587→        }
   588→
   589→        // Same-layer comparisons: use original conservative logic
   590→        // If similarity is very high (>0.8), trust keyword matching
   591→        if simple_sim > 0.8 {
   592→            return simple_sim;
   593→        }
   594→
   595→        // For moderate similarity (0.4-0.8), use AI to disambiguate
   596→        // This catches same-layer duplicates that keyword matching misses
   597→        if simple_sim >= 0.4
   598→            && let Some(ai_sim) = ai.semantic_similarity(text1, text2, layer1, layer2) {
   599→                // Blend simple and AI similarity (weighted average)
   600→                // Give more weight to AI for disambiguation
   601→                return simple_sim * 0.3 + ai_sim * 0.7;
   602→            }
   603→
   604→        // For very low similarity (<0.4) in same layer, skip AI (too expensive, low probability)
   605→        simple_sim
   606→    }
   607→
   608→    /// Infer edge kind between two nodes
   609→    fn infer_edge_kind(
   610→        &self,
   611→        source: &crate::SpecNodeData,
   612→        target: &crate::SpecNodeData,
   613→        similarity: f32,
   614→    ) -> Option<(EdgeKind, f32, String)> {
   615→        // Rule 1: Synonym - very high similarity, same kind
   616→        // Check this FIRST because it's most specific (highest threshold)
   617→        if similarity > 0.8 && source.kind == target.kind {
   618→            return Some((
   619→                EdgeKind::Synonym,
   620→                similarity * 0.95,
   621→                "Nearly identical content".to_string(),
   622→            ));
   623→        }
   624→
   625→        // Rule 2: Formalizes - same concept, different formality levels
   626→        if similarity > 0.5 && source.formality_layer < target.formality_layer {
   627→            return Some((
   628→                EdgeKind::Formalizes,
   629→                similarity * 0.9,
   630→                format!(
   631→                    "Same concept at different formality levels ({} -> {})",
   632→                    source.formality_layer, target.formality_layer
   633→                ),
   634→            ));
   635→        }
   636→
   637→        // Rule 3: DerivesFrom - assertion derives from constraint
   638→        if similarity > 0.5
   639→            && source.kind == NodeKind::Assertion
   640→            && target.kind == NodeKind::Constraint
   641→        {
   642→            return Some((
   643→                EdgeKind::DerivesFrom,
   644→                similarity * 0.8,
   645→                "Assertion derives from constraint".to_string(),
   646→            ));
   647→        }
   648→
   649→        // Rule 4: Refines - scenario refines constraint, or same kind with high similarity
   650→        if similarity > 0.6 {
   651→            if source.kind == NodeKind::Scenario && target.kind == NodeKind::Constraint {
   652→                return Some((
   653→                    EdgeKind::Refines,
   654→                    similarity * 0.85,
   655→                    "Scenario refines constraint".to_string(),
   656→                ));
   657→            }
   658→            if source.kind == target.kind {
   659→                return Some((
   660→                    EdgeKind::Refines,
   661→                    similarity * 0.9,
   662→                    "Similar specifications (potential refinement)".to_string(),
   663→                ));
   664→            }
   665→        }
   666→
   667→        // Rule 5: Same source file suggests relationship
   668→        if let (Some(src_file), Some(tgt_file)) = (
   669→            source.metadata.get("source_file"),
   670→            target.metadata.get("source_file"),
   671→        )
   672→            && src_file == tgt_file && similarity > 0.4 {
   673→                return Some((
   674→                    EdgeKind::Refines,
   675→                    similarity * 0.7,
   676→                    "Same source file".to_string(),
   677→                ));
   678→            }
   679→
   680→        None
   681→    }
   682→}
