   687→impl RustExtractor {
   688→    /// Extract specifications from Rust file
   689→    pub fn extract(file_path: &Path) -> Result<Vec<InferredSpecification>, String> {
   690→        let content = std::fs::read_to_string(file_path)
   691→            .map_err(|e| format!("Failed to read file: {}", e))?;
   692→
   693→        let mut specs = Vec::new();
   694→
   695→        // Extract from function names (conventions like validate_*, check_*, require_*)
   696→        specs.extend(Self::extract_from_function_names(&content, file_path)?);
   697→
   698→        // Extract from assertions (assert!, assert_eq!, debug_assert!)
   699→        specs.extend(Self::extract_from_assertions(&content, file_path)?);
   700→
   701→        // Extract from test functions
   702→        specs.extend(Self::extract_from_tests(&content, file_path)?);
   703→
   704→        // Extract from doc comments
   705→        specs.extend(Self::extract_from_docs(&content, file_path)?);
   706→
   707→        // Extract from panic messages
   708→        specs.extend(Self::extract_from_panics(&content, file_path)?);
   709→
   710→        Ok(specs)
   711→    }
   712→
   713→    fn extract_from_function_names(
   714→        content: &str,
   715→        file_path: &Path,
   716→    ) -> Result<Vec<InferredSpecification>, String> {
   717→        let mut specs = Vec::new();
   718→        let file_name = file_path.to_string_lossy().to_string();
   719→
   720→        for (line_num, line) in content.lines().enumerate() {
   721→            // Match function definitions
   722→            if let Some(fn_name) = Self::extract_fn_name(line) {
   723→                // Convention-based inference
   724→                let (kind, confidence, description) = if fn_name.starts_with("validate_") {
   725→                    (NodeKind::Constraint, 0.8, format!("Must {}", fn_name.strip_prefix("validate_").unwrap().replace('_', " ")))
   726→                } else if fn_name.starts_with("check_") {
   727→                    (NodeKind::Constraint, 0.75, format!("Must {}", fn_name.strip_prefix("check_").unwrap().replace('_', " ")))
   728→                } else if fn_name.starts_with("require_") {
   729→                    (NodeKind::Constraint, 0.85, format!("Requires {}", fn_name.strip_prefix("require_").unwrap().replace('_', " ")))
   730→                } else if fn_name.starts_with("test_") {
   731→                    (NodeKind::Scenario, 0.9, fn_name.strip_prefix("test_").unwrap().replace('_', " "))
   732→                } else {
   733→                    continue;
   734→                };
   735→
   736→                specs.push(InferredSpecification {
   737→                    content: description,
   738→                    kind,
   739→                    confidence,
   740→                    source_file: file_name.clone(),
   741→                    source_line: line_num + 1,
   742→                    formality_layer: 1, // Structured (from naming convention)
   743→                    metadata: HashMap::from([
   744→                        ("function".to_string(), fn_name.to_string()),
   745→                        ("extractor".to_string(), "function_name".to_string()),
   746→                    ]),
   747→                });
   748→            }
   749→        }
   750→
   751→        Ok(specs)
   752→    }
   753→
   754→    fn extract_from_assertions(
   755→        content: &str,
   756→        file_path: &Path,
   757→    ) -> Result<Vec<InferredSpecification>, String> {
   758→        let mut specs = Vec::new();
   759→        let file_name = file_path.to_string_lossy().to_string();
   760→
   761→        for (line_num, line) in content.lines().enumerate() {
   762→            // Match assert!, assert_eq!, debug_assert!, etc.
   763→            if let Some(assertion) = Self::extract_assertion(line) {
   764→                specs.push(InferredSpecification {
   765→                    content: format!("Invariant: {}", assertion),
   766→                    kind: NodeKind::Constraint,
   767→                    confidence: 0.95, // Assertions are high-confidence constraints
   768→                    source_file: file_name.clone(),
   769→                    source_line: line_num + 1,
   770→                    formality_layer: 3, // Executable (actual code)
   771→                    metadata: HashMap::from([
   772→                        ("assertion".to_string(), assertion.clone()),
   773→                        ("extractor".to_string(), "assertion".to_string()),
   774→                    ]),
   775→                });
   776→            }
   777→        }
   778→
   779→        Ok(specs)
