   782→    fn extract_from_tests(
   783→        content: &str,
   784→        file_path: &Path,
   785→    ) -> Result<Vec<InferredSpecification>, String> {
   786→        let mut specs = Vec::new();
   787→        let file_name = file_path.to_string_lossy().to_string();
   788→
   789→        let mut in_test = false;
   790→        let mut test_name = String::new();
   791→        let mut test_body = String::new();
   792→        let mut test_start_line = 0;
   793→
   794→        for (line_num, line) in content.lines().enumerate() {
   795→            let trimmed = line.trim();
   796→
   797→            // Detect #[test] or #[cfg(test)]
   798→            if trimmed.starts_with("#[test]") || trimmed.contains("#[test]") {
   799→                in_test = true;
   800→                test_start_line = line_num + 1;
   801→                test_body.clear();
   802→            } else if in_test && trimmed.starts_with("fn ") {
   803→                if let Some(name) = Self::extract_fn_name(trimmed) {
   804→                    test_name = name.to_string();
   805→                }
   806→            } else if in_test && !test_name.is_empty() {
   807→                // Collect test body for AI analysis
   808→                test_body.push_str(line);
   809→                test_body.push('\n');
   810→
   811→                if trimmed == "}" {
   812→                    // End of test function
   813→
   814→                    // Extract U3 test scenario (the test itself)
   815→                    let scenario_name = test_name.strip_prefix("test_").unwrap_or(&test_name).replace('_', " ");
   816→                    specs.push(InferredSpecification {
   817→                        content: format!("Scenario: {}", scenario_name),
   818→                        kind: NodeKind::Scenario,
   819→                        confidence: 0.9,
   820→                        source_file: file_name.clone(),
   821→                        source_line: test_start_line,
   822→                        formality_layer: 3, // U3 - Executable test
   823→                        metadata: HashMap::from([
   824→                            ("test_function".to_string(), test_name.clone()),
   825→                            ("extractor".to_string(), "test".to_string()),
   826→                        ]),
   827→                    });
   828→
   829→                    // Extract U0 requirement via AI (reverse mapping f₀₃⁻¹: U3 → U0)
   830→                    if let Some(u0_spec) = Self::extract_intent_from_test_with_ai(&test_name, &test_body) {
   831→                        specs.push(InferredSpecification {
   832→                            content: u0_spec,
   833→                            kind: NodeKind::Constraint, // Root requirements are constraints
   834→                            confidence: 0.95, // AI-extracted intent is high confidence
   835→                            source_file: file_name.clone(),
   836→                            source_line: test_start_line,
   837→                            formality_layer: 0, // U0 - root specification inferred from U3
   838→                            metadata: HashMap::from([
   839→                                ("test_function".to_string(), test_name.clone()),
   840→                                ("extractor".to_string(), "ai_intent".to_string()),
   841→                                ("reverse_mapping".to_string(), "f_03_inverse".to_string()),
   842→                                ("derived_from_u3".to_string(), "true".to_string()),
   843→                            ]),
   844→                        });
   845→                    }
   846→
   847→                    in_test = false;
   848→                    test_name.clear();
   849→                    test_body.clear();
   850→                }
   851→            }
   852→        }
   853→
   854→        Ok(specs)
   855→    }
   856→
   857→    /// Extract the INTENT behind a test using AI (reverse mapping f₀₃⁻¹: U3 → U0)
   858→    ///
   859→    /// This is the core of the reverse mapping engine. Instead of just pattern-matching
   860→    /// test names, we use AI to understand what requirement the test is verifying.
   861→    fn extract_intent_from_test_with_ai(test_name: &str, test_body: &str) -> Option<String> {
   862→        use std::process::{Command, Stdio};
   863→
   864→        // Check if claude CLI is available
   865→        let available = Command::new("claude")
   866→            .arg("--version")
   867→            .stdout(Stdio::null())
   868→            .stderr(Stdio::null())
   869→            .status()
   870→            .is_ok();
   871→
   872→        if !available {
   873→            // Fallback to simple name-based extraction if AI unavailable
   874→            return None;
   875→        }
   876→
   877→        let prompt = format!(
   878→            r#"You are analyzing a test function to extract the root specification (U0) it verifies.
   879→
   880→Test name: {}
   881→Test code:
   882→{}
   883→
   884→Task: Extract the fundamental REQUIREMENT or CONSTRAINT that this test is verifying.
   885→Output ONLY a single sentence specification in natural language, starting with "The system must..." or "System must..." or similar.
   886→
   887→Focus on:
   888→- What requirement is being tested? (not how it's tested)
   889→- What constraint must the system satisfy?
   890→- What capability must the system provide?
   891→
   892→Output format: Single sentence, no explanation, no code, just the requirement.
   893→Example output: "The system must detect contradictions when password length requirements conflict"
   894→"#,
   895→            test_name, test_body
   896→        );
   897→
   898→        let output = Command::new("claude")
   899→            .arg("-p")
   900→            .arg(&prompt)
   901→            .output()
   902→            .ok()?;
   903→
   904→        if !output.status.success() {
   905→            return None;
   906→        }
   907→
   908→        let response = String::from_utf8(output.stdout).ok()?;
   909→        let spec = response.trim();
   910→
   911→        // Validate that we got a reasonable specification
   912→        if spec.is_empty() || spec.len() < 20 || spec.len() > 500 {
   913→            return None;
   914→        }
   915→
   916→        // Check that it's a specification (contains requirement keywords)
   917→        let requirement_keywords = ["must", "shall", "should", "system", "require"];
   918→        let has_requirement = requirement_keywords.iter()
   919→            .any(|kw| spec.to_lowercase().contains(kw));
   920→
   921→        if !has_requirement {
   922→            return None;
   923→        }
   924→
   925→        Some(spec.to_string())
   926→    }
