   928→    fn extract_from_docs(
   929→        content: &str,
   930→        file_path: &Path,
   931→    ) -> Result<Vec<InferredSpecification>, String> {
   932→        let mut specs = Vec::new();
   933→        let file_name = file_path.to_string_lossy().to_string();
   934→
   935→        for (line_num, line) in content.lines().enumerate() {
   936→            let trimmed = line.trim();
   937→
   938→            // Match /// or //! doc comments
   939→            if let Some(doc) = trimmed.strip_prefix("///").or_else(|| trimmed.strip_prefix("//!")) {
   940→                let doc_text = doc.trim();
   941→
   942→                // Look for specification keywords
   943→                let (kind, confidence) = if doc_text.contains("must") || doc_text.contains("shall") || doc_text.contains("required") {
   944→                    (NodeKind::Constraint, 0.8)
   945→                } else if doc_text.contains("should") || doc_text.contains("expected") {
   946→                    (NodeKind::Assertion, 0.7)
   947→                } else if doc_text.contains("example") || doc_text.contains("scenario") {
   948→                    (NodeKind::Scenario, 0.6)
   949→                } else {
   950→                    continue; // Not a specification
   951→                };
   952→
   953→                if !doc_text.is_empty() {
   954→                    specs.push(InferredSpecification {
   955→                        content: doc_text.to_string(),
   956→                        kind,
   957→                        confidence,
   958→                        source_file: file_name.clone(),
   959→                        source_line: line_num + 1,
   960→                        formality_layer: 0, // Natural language
   961→                        metadata: HashMap::from([
   962→                            ("doc_comment".to_string(), "true".to_string()),
   963→                            ("extractor".to_string(), "doc".to_string()),
   964→                        ]),
   965→                    });
   966→                }
   967→            }
   968→        }
   969→
   970→        Ok(specs)
   971→    }
