  1001→    // Helper parsers
  1002→
  1003→    fn extract_fn_name(line: &str) -> Option<String> {
  1004→        let trimmed = line.trim();
  1005→        if trimmed.starts_with("fn ") || trimmed.starts_with("pub fn ") {
  1006→            let after_fn = trimmed.split("fn ").nth(1)?;
  1007→            let name = after_fn.split('(').next()?.trim();
  1008→            Some(name.to_string())
  1009→        } else {
  1010→            None
  1011→        }
  1012→    }
  1013→
  1014→    fn extract_assertion(line: &str) -> Option<String> {
  1015→        let trimmed = line.trim();
  1016→
  1017→        // Match assert!(...), assert_eq!(...), etc.
  1018→        for macro_name in &["assert!", "assert_eq!", "assert_ne!", "debug_assert!"] {
  1019→            if let Some(idx) = trimmed.find(macro_name) {
  1020→                let after_macro = &trimmed[idx + macro_name.len()..];
  1021→                if let Some(start) = after_macro.find('(')
  1022→                    && let Some(end) = after_macro.rfind(')') {
  1023→                        let assertion = &after_macro[start + 1..end];
  1024→                        return Some(assertion.trim().to_string());
  1025→                    }
  1026→            }
  1027→        }
  1028→
  1029→        None
  1030→    }
  1031→
  1032→    fn extract_panic_message(line: &str) -> Option<String> {
  1033→        let trimmed = line.trim();
  1034→
  1035→        if let Some(idx) = trimmed.find("panic!(") {
  1036→            let after_panic = &trimmed[idx + 7..];
  1037→            if let Some(start) = after_panic.find('"')
  1038→                && let Some(end) = after_panic[start + 1..].find('"') {
  1039→                    let message = &after_panic[start + 1..start + 1 + end];
  1040→                    return Some(message.to_string());
  1041→                }
  1042→        }
  1043→
  1044→        None
  1045→    }
  1046→}
