  1255→/// Extract specifications from documentation files (Markdown)
  1256→pub struct DocExtractor;
  1257→
  1258→impl DocExtractor {
  1259→    /// Extract specifications from Markdown documentation
  1260→    pub fn extract(file_path: &Path) -> Result<Vec<InferredSpecification>, String> {
  1261→        let content = std::fs::read_to_string(file_path)
  1262→            .map_err(|e| format!("Failed to read file: {}", e))?;
  1263→
  1264→        let mut specs = Vec::new();
  1265→        let file_name = file_path.to_string_lossy().to_string();
  1266→
  1267→        // Process line by line
  1268→        for (line_num, line) in content.lines().enumerate() {
  1269→            let trimmed = line.trim();
  1270→
  1271→            // Skip empty lines, headings, and code blocks
  1272→            if trimmed.is_empty() || trimmed.starts_with('#') || trimmed.starts_with("```") {
  1273→                continue;
  1274→            }
  1275→
  1276→            // Look for specification patterns
  1277→            if let Some(spec) = Self::extract_specification(trimmed, &file_name, line_num + 1) {
  1278→                specs.push(spec);
  1279→            }
  1280→        }
  1281→
  1282→        Ok(specs)
  1283→    }
  1284→
  1285→    fn extract_specification(line: &str, file_name: &str, line_num: usize) -> Option<InferredSpecification> {
  1286→        // Specification markers indicating requirements/constraints
  1287→        let constraint_markers = ["must", "shall", "required", "constraint"];
  1288→        let assertion_markers = ["should", "can", "will", "provides", "supports"];
  1289→        let scenario_markers = ["when", "given", "example", "scenario"];
  1290→
  1291→        let lower = line.to_lowercase();
  1292→
  1293→        // Determine kind based on markers
  1294→        let (kind, confidence_base) = if constraint_markers.iter().any(|m| lower.contains(m)) {
  1295→            (NodeKind::Constraint, 0.85)
  1296→        } else if assertion_markers.iter().any(|m| lower.contains(m)) {
  1297→            (NodeKind::Assertion, 0.75)
  1298→        } else if scenario_markers.iter().any(|m| lower.contains(m)) {
  1299→            (NodeKind::Scenario, 0.70)
  1300→        } else {
  1301→            return None; // Not a specification
  1302→        };
  1303→
  1304→        // Skip if line is too short (likely not a complete specification)
  1305→        if line.len() < 20 {
  1306→            return None;
  1307→        }
  1308→
  1309→        // Clean up markdown formatting
  1310→        let content = Self::clean_markdown(line);
  1311→
  1312→        // Adjust confidence based on content quality
  1313→        let confidence: f32 = if content.len() > 50 && content.contains("system") {
  1314→            confidence_base + 0.1
  1315→        } else {
  1316→            confidence_base
  1317→        };
  1318→
  1319→        // Determine formality layer based on content
  1320→        let formality_layer = if lower.contains("formally") || lower.contains("proof") {
  1321→            1 // U1: More formal specification
  1322→        } else {
  1323→            0 // U0: Natural language requirement
  1324→        };
  1325→
  1326→        Some(InferredSpecification {
  1327→            content,
  1328→            kind,
  1329→            confidence: confidence.min(0.95),
  1330→            source_file: file_name.to_string(),
  1331→            source_line: line_num,
  1332→            formality_layer,
  1333→            metadata: HashMap::from([
  1334→                ("extractor".to_string(), "documentation".to_string()),
  1335→            ]),
  1336→        })
  1337→    }
  1338→
  1339→    fn clean_markdown(text: &str) -> String {
  1340→        // Remove common markdown formatting
  1341→        let mut cleaned = text.to_string();
  1342→
  1343→        // Remove bold/italic markers
  1344→        cleaned = cleaned.replace("**", "");
  1345→        cleaned = cleaned.replace("__", "");
  1346→        cleaned = cleaned.replace("*", "");
  1347→        cleaned = cleaned.replace("_", "");
  1348→
  1349→        // Remove list markers
  1350→        if let Some(stripped) = cleaned.strip_prefix("- ") {
  1351→            cleaned = stripped.to_string();
  1352→        }
  1353→        if let Some(stripped) = cleaned.strip_prefix("* ") {
  1354→            cleaned = stripped.to_string();
  1355→        }
  1356→
  1357→        // Remove numbered list markers (e.g., "1. ")
  1358→        if let Some(pos) = cleaned.find(". ")
  1359→            && cleaned[..pos].chars().all(|c| c.is_numeric()) {
  1360→                cleaned = cleaned[pos + 2..].to_string();
  1361→            }
  1362→
  1363→        cleaned.trim().to_string()
  1364→    }
  1365→}
