  1367→/// Extract architectural properties from code files
  1368→/// This enables automatic detection of architectural violations
  1369→pub struct ArchitectureExtractor;
  1370→
  1371→impl ArchitectureExtractor {
  1372→    /// Extract architectural properties from a source file
  1373→    /// Returns specifications about file size, module structure, etc.
  1374→    pub fn extract(file_path: &Path) -> Result<Vec<InferredSpecification>, String> {
  1375→        let content = std::fs::read_to_string(file_path)
  1376→            .map_err(|e| format!("Failed to read file: {}", e))?;
  1377→
  1378→        let mut specs = Vec::new();
  1379→        let file_name = file_path.to_string_lossy().to_string();
  1380→        let line_count = content.lines().count();
  1381→
  1382→        // Extract file size metrics
  1383→        // This will create assertions like "spec-cli/src/main.rs has 2172 lines of code"
  1384→        // These are U3 (implementation facts) that can contradict U0 architectural requirements
  1385→        let size_spec = Self::extract_file_size(&file_name, line_count);
  1386→        specs.push(size_spec);
  1387→
  1388→        // Extract module structure if it's a Rust file
  1389→        if file_path.extension().and_then(|s| s.to_str()) == Some("rs")
  1390→            && let Some(module_spec) = Self::extract_module_structure(&content, &file_name) {
  1391→                specs.push(module_spec);
  1392→            }
  1393→
  1394→        Ok(specs)
  1395→    }
  1396→
  1397→    fn extract_file_size(file_name: &str, line_count: usize) -> InferredSpecification {
  1398→        let content = format!("{} contains {} lines of code", file_name, line_count);
  1399→
  1400→        // High confidence - this is a verifiable fact
  1401→        let confidence = 1.0;
  1402→
  1403→        InferredSpecification {
  1404→            content,
  1405→            kind: NodeKind::Assertion,
  1406→            confidence,
  1407→            source_file: file_name.to_string(),
  1408→            source_line: 0, // File-level property
  1409→            formality_layer: 3, // U3: Implementation fact
  1410→            metadata: HashMap::from([
  1411→                ("extractor".to_string(), "architecture".to_string()),
  1412→                ("property".to_string(), "file_size".to_string()),
  1413→                ("line_count".to_string(), line_count.to_string()),
  1414→            ]),
  1415→        }
  1416→    }
  1417→
  1418→    fn extract_module_structure(content: &str, file_name: &str) -> Option<InferredSpecification> {
  1419→        // Count modules, functions, structs, etc.
  1420→        let mut module_count = 0;
  1421→        let mut function_count = 0;
  1422→        let mut struct_count = 0;
  1423→
  1424→        for line in content.lines() {
  1425→            let trimmed = line.trim();
  1426→            if trimmed.starts_with("mod ") && !trimmed.contains("//") {
  1427→                module_count += 1;
  1428→            }
  1429→            if (trimmed.starts_with("fn ") || trimmed.starts_with("pub fn ") || trimmed.starts_with("async fn "))
  1430→                && !trimmed.contains("//") {
  1431→                function_count += 1;
  1432→            }
  1433→            if (trimmed.starts_with("struct ") || trimmed.starts_with("pub struct "))
  1434→                && !trimmed.contains("//") {
  1435→                struct_count += 1;
  1436→            }
  1437→        }
  1438→
  1439→        // Only create spec if there's meaningful structure
  1440→        if function_count > 0 || struct_count > 0 {
  1441→            let content = format!(
  1442→                "{} contains {} functions, {} structs, {} modules",
  1443→                file_name, function_count, struct_count, module_count
  1444→            );
  1445→
  1446→            Some(InferredSpecification {
  1447→                content,
  1448→                kind: NodeKind::Assertion,
  1449→                confidence: 0.95,
  1450→                source_file: file_name.to_string(),
  1451→                source_line: 0,
  1452→                formality_layer: 3, // U3: Implementation fact
  1453→                metadata: HashMap::from([
  1454→                    ("extractor".to_string(), "architecture".to_string()),
  1455→                    ("property".to_string(), "module_structure".to_string()),
  1456→                    ("function_count".to_string(), function_count.to_string()),
  1457→                    ("struct_count".to_string(), struct_count.to_string()),
  1458→                    ("module_count".to_string(), module_count.to_string()),
  1459→                ]),
  1460→            })
  1461→        } else {
  1462→            None
  1463→        }
  1464→    }
  1465→}
