/// Extract U2 specifications from Protocol Buffer (.proto) files
pub struct ProtoExtractor;

impl ProtoExtractor {
    /// Extract RPC interface specifications from proto file
    pub fn extract(file_path: &Path) -> Result<Vec<InferredSpecification>, String> {
        let content = std::fs::read_to_string(file_path)
            .map_err(|e| format!("Failed to read file: {}", e))?;

        let mut specs = Vec::new();
        let file_name = file_path.to_string_lossy().to_string();

        // Extract RPC definitions
        let mut current_comment = String::new();
        for (line_num, line) in content.lines().enumerate() {
            let trimmed = line.trim();

            // Capture comment lines
            if trimmed.starts_with("//") {
                let comment = trimmed.trim_start_matches("//").trim();
                if !comment.is_empty() {
                    current_comment = comment.to_string();
                }
                continue;
            }

            // Match RPC definitions: "rpc MethodName(RequestType) returns (ResponseType);"
            if trimmed.starts_with("rpc ")
                && let Some(rpc_name) = Self::extract_rpc_name(trimmed) {
                    let description = if !current_comment.is_empty() {
                        current_comment.clone()
                    } else {
                        // Generate description from RPC name
                        Self::rpc_name_to_description(&rpc_name)
                    };

                    specs.push(InferredSpecification {
                        content: description,
                        kind: NodeKind::Assertion, // RPC interface is an assertion about behavior
                        confidence: 0.95, // High confidence - explicitly defined interface
                        source_file: file_name.clone(),
                        source_line: line_num + 1,
                        formality_layer: 2, // U2: Interface/API specification
                        metadata: HashMap::from([
                            ("rpc_name".to_string(), rpc_name.clone()),
                            ("extractor".to_string(), "proto_rpc".to_string()),
                        ]),
                    });

                    current_comment.clear();
                }
        }

        Ok(specs)
    }

    fn extract_rpc_name(line: &str) -> Option<String> {
        // Parse "rpc MethodName(Request) returns (Response);"
        let after_rpc = line.strip_prefix("rpc ")?.trim();
        let name = after_rpc.split('(').next()?.trim();
        Some(name.to_string())
    }

    fn rpc_name_to_description(rpc_name: &str) -> String {
        // Convert camelCase/PascalCase to sentence
        // AddNode -> "RPC: Add node"
        // DetectContradictions -> "RPC: Detect contradictions"
        let mut result = String::new();
        let mut prev_was_lower = false;

        for (i, ch) in rpc_name.chars().enumerate() {
            if ch.is_uppercase() && prev_was_lower {
                result.push(' ');
                result.push(ch.to_lowercase().next().unwrap());
            } else if i == 0 {
                // First character stays as-is
                result.push(ch);
            } else {
                result.push(ch.to_lowercase().next().unwrap());
            }
            prev_was_lower = ch.is_lowercase();
        }

        format!("RPC: {}", result)
    }
}

/// Extract specifications from documentation files (Markdown)
pub struct DocExtractor;

impl DocExtractor {
    /// Extract specifications from Markdown documentation
    pub fn extract(file_path: &Path) -> Result<Vec<InferredSpecification>, String> {
        let content = std::fs::read_to_string(file_path)
            .map_err(|e| format!("Failed to read file: {}", e))?;

        let mut specs = Vec::new();
        let file_name = file_path.to_string_lossy().to_string();

        // Process line by line
        for (line_num, line) in content.lines().enumerate() {
            let trimmed = line.trim();

            // Skip empty lines, headings, and code blocks
            if trimmed.is_empty() || trimmed.starts_with('#') || trimmed.starts_with("```") {
                continue;
            }

            // Look for specification patterns
            if let Some(spec) = Self::extract_specification(trimmed, &file_name, line_num + 1) {
                specs.push(spec);
            }
        }

        Ok(specs)
    }

    fn extract_specification(line: &str, file_name: &str, line_num: usize) -> Option<InferredSpecification> {
        // Specification markers indicating requirements/constraints
        let constraint_markers = ["must", "shall", "required", "constraint"];
        let assertion_markers = ["should", "can", "will", "provides", "supports"];
        let scenario_markers = ["when", "given", "example", "scenario"];

        let lower = line.to_lowercase();

        // Determine kind based on markers
        let (kind, confidence_base) = if constraint_markers.iter().any(|m| lower.contains(m)) {
            (NodeKind::Constraint, 0.85)
        } else if assertion_markers.iter().any(|m| lower.contains(m)) {
            (NodeKind::Assertion, 0.75)
        } else if scenario_markers.iter().any(|m| lower.contains(m)) {
            (NodeKind::Scenario, 0.70)
        } else {
            return None; // Not a specification
        };

        // Skip if line is too short (likely not a complete specification)
        if line.len() < 20 {
            return None;
        }

        // Clean up markdown formatting
        let content = Self::clean_markdown(line);

        // Adjust confidence based on content quality
        let confidence: f32 = if content.len() > 50 && content.contains("system") {
            confidence_base + 0.1
        } else {
            confidence_base
        };

        // Determine formality layer based on content
        let formality_layer = if lower.contains("formally") || lower.contains("proof") {
            1 // U1: More formal specification
        } else {
            0 // U0: Natural language requirement
        };

        Some(InferredSpecification {
            content,
            kind,
            confidence: confidence.min(0.95),
            source_file: file_name.to_string(),
            source_line: line_num,
            formality_layer,
            metadata: HashMap::from([
                ("extractor".to_string(), "documentation".to_string()),
            ]),
        })
    }

    fn clean_markdown(text: &str) -> String {
        // Remove common markdown formatting
        let mut cleaned = text.to_string();

        // Remove bold/italic markers
        cleaned = cleaned.replace("**", "");
        cleaned = cleaned.replace("__", "");
        cleaned = cleaned.replace("*", "");
        cleaned = cleaned.replace("_", "");

        // Remove list markers
        if let Some(stripped) = cleaned.strip_prefix("- ") {
            cleaned = stripped.to_string();
        }
        if let Some(stripped) = cleaned.strip_prefix("* ") {
            cleaned = stripped.to_string();
        }

        // Remove numbered list markers (e.g., "1. ")
        if let Some(pos) = cleaned.find(". ")
            && cleaned[..pos].chars().all(|c| c.is_numeric()) {
                cleaned = cleaned[pos + 2..].to_string();
            }

        cleaned.trim().to_string()
    }
}

/// Extract architectural properties from code files
/// This enables automatic detection of architectural violations
pub struct ArchitectureExtractor;

impl ArchitectureExtractor {
    /// Extract architectural properties from a source file
    /// Returns specifications about file size, module structure, etc.
    pub fn extract(file_path: &Path) -> Result<Vec<InferredSpecification>, String> {
        let content = std::fs::read_to_string(file_path)
            .map_err(|e| format!("Failed to read file: {}", e))?;

        let mut specs = Vec::new();
        let file_name = file_path.to_string_lossy().to_string();
        let line_count = content.lines().count();

        // Extract file size metrics
        // This will create assertions like "spec-cli/src/main.rs has 2172 lines of code"
        // These are U3 (implementation facts) that can contradict U0 architectural requirements
        let size_spec = Self::extract_file_size(&file_name, line_count);
        specs.push(size_spec);

        // Extract module structure if it's a Rust file
        if file_path.extension().and_then(|s| s.to_str()) == Some("rs")
            && let Some(module_spec) = Self::extract_module_structure(&content, &file_name) {
                specs.push(module_spec);
            }

        Ok(specs)
    }

    fn extract_file_size(file_name: &str, line_count: usize) -> InferredSpecification {
        let content = format!("{} contains {} lines of code", file_name, line_count);

        // High confidence - this is a verifiable fact
        let confidence = 1.0;

        InferredSpecification {
            content,
            kind: NodeKind::Assertion,
            confidence,
            source_file: file_name.to_string(),
            source_line: 0, // File-level property
            formality_layer: 3, // U3: Implementation fact
            metadata: HashMap::from([
                ("extractor".to_string(), "architecture".to_string()),
                ("property".to_string(), "file_size".to_string()),
                ("line_count".to_string(), line_count.to_string()),
            ]),
        }
    }

    fn extract_module_structure(content: &str, file_name: &str) -> Option<InferredSpecification> {
        // Count modules, functions, structs, etc.
        let mut module_count = 0;
        let mut function_count = 0;
        let mut struct_count = 0;

        for line in content.lines() {
            let trimmed = line.trim();
            if trimmed.starts_with("mod ") && !trimmed.contains("//") {
                module_count += 1;
            }
            if (trimmed.starts_with("fn ") || trimmed.starts_with("pub fn ") || trimmed.starts_with("async fn "))
                && !trimmed.contains("//") {
                function_count += 1;
            }
            if (trimmed.starts_with("struct ") || trimmed.starts_with("pub struct "))
                && !trimmed.contains("//") {
                struct_count += 1;
            }
        }

        // Only create spec if there's meaningful structure
        if function_count > 0 || struct_count > 0 {
            let content = format!(
                "{} contains {} functions, {} structs, {} modules",
                file_name, function_count, struct_count, module_count
            );

            Some(InferredSpecification {
                content,
                kind: NodeKind::Assertion,
                confidence: 0.95,
                source_file: file_name.to_string(),
                source_line: 0,
                formality_layer: 3, // U3: Implementation fact
                metadata: HashMap::from([
                    ("extractor".to_string(), "architecture".to_string()),
                    ("property".to_string(), "module_structure".to_string()),
                    ("function_count".to_string(), function_count.to_string()),
                    ("struct_count".to_string(), struct_count.to_string()),
                    ("module_count".to_string(), module_count.to_string()),
                ]),
            })
        } else {
            None
        }
    }
}

/// Extract specifications from PHP test files (PHPUnit)
///
/// Supports PHPUnit tests with #[Test] attributes:
/// ```php
/// #[Test]
/// public function fixtureReturnsArray(): void {
///     // test body
/// }
/// ```
pub struct PHPTestExtractor;

impl PHPTestExtractor {
    /// Extract specifications from PHP test file
    pub fn extract(file_path: &Path) -> Result<Vec<InferredSpecification>, String> {
        let content = std::fs::read_to_string(file_path)
            .map_err(|e| format!("Failed to read file: {}", e))?;

        let mut specs = Vec::new();
        let file_name = file_path.to_string_lossy().to_string();

        let mut has_test_attribute = false;
        let mut test_start_line = 0;

        for (line_num, line) in content.lines().enumerate() {
            let trimmed = line.trim();

            // Detect #[Test] attribute
            if trimmed == "#[Test]" || trimmed.starts_with("#[Test") {
                has_test_attribute = true;
                test_start_line = line_num + 2; // Next line is function declaration
            } else if has_test_attribute && trimmed.starts_with("public function ") {
                // Extract test method name
                if let Some(name) = Self::extract_test_method_name(trimmed) {
                    // Convert camelCase to human-readable scenario
                    let scenario_name = Self::convert_camel_case_to_readable(&name);

                    specs.push(InferredSpecification {
                        content: format!("Test scenario: {}", scenario_name),
                        kind: NodeKind::Scenario,
                        confidence: 0.85,
                        source_file: file_name.clone(),
                        source_line: test_start_line,
                        formality_layer: 3, // U3 - Executable test
                        metadata: HashMap::from([
                            ("test_method".to_string(), name.clone()),
                            ("extractor".to_string(), "php_test".to_string()),
                            ("test_framework".to_string(), "phpunit".to_string()),
                        ]),
                    });
                }
                has_test_attribute = false;
            }
        }

        Ok(specs)
    }

    /// Extract test method name from PHP function declaration
    fn extract_test_method_name(line: &str) -> Option<String> {
        // Match: public function testName(): void
        let parts: Vec<&str> = line.split_whitespace().collect();
        for (i, part) in parts.iter().enumerate() {
            if *part == "function" && i + 1 < parts.len() {
                let name = parts[i + 1];
                // Remove parentheses and return type
                let name = name.split('(').next().unwrap_or(name);
                return Some(name.to_string());
            }
        }
        None
    }

    /// Convert camelCase to human-readable format
    /// Example: "fixtureReturnsArray" → "fixture returns array"
    fn convert_camel_case_to_readable(name: &str) -> String {
        let mut result = String::new();
        let mut prev_lowercase = false;

        for ch in name.chars() {
            if ch.is_uppercase() {
                if prev_lowercase {
                    result.push(' ');
                }
                result.push(ch.to_ascii_lowercase());
                prev_lowercase = false;
            } else {
                result.push(ch);
                prev_lowercase = true;
            }
        }

        result
    }
}

