     1→/// Bidirectional synchronization between SpecRepository (data layer) and UDAFModel (formal layer)
     2→///
     3→/// This module provides the bridge layer that:
     4→/// 1. Reads specifications from SpecRepository and populates UDAFModel
     5→/// 2. Writes verification results back to SpecRepository as metadata
     6→///
     7→/// Key differences from populate.rs:
     8→/// - Works with SpecRepository instead of SpecGraph
     9→/// - Bidirectional (can write results back)
    10→/// - Stateless (pure functions, no internal state)
    11→/// - Uses consolidated constraint extraction
    12→use crate::data::SpecRepository;
    13→use crate::formal::model::constraint::extract_constraints_from_text;
    14→use crate::formal::*;
    15→use crate::data::{NodeKind, EdgeKind};
    16→use chrono::Utc;
    17→use std::collections::HashMap;
