    19→/// Stateless synchronization utilities
    20→pub struct ModelSync;
    21→
    22→impl ModelSync {
    23→    /// Synchronize UDAFModel from SpecRepository
    24→    ///
    25→    /// This populates the formal model by reading nodes and edges from the repository:
    26→    /// - Universes are created based on formality_layer (0=U0, 1=U1, etc.)
    27→    /// - Domains are extracted from Domain nodes
    28→    /// - Admissible sets are created for each specification
    29→    /// - Constraints are extracted from node content
    30→    /// - Transform functions are built from edge relationships
    31→    ///
    32→    /// Returns Ok(()) on success, or Err with error message.
    33→    pub fn sync_from_repository(model: &mut UDAFModel, repo: &SpecRepository) -> Result<(), String> {
    34→        // Clear existing data
    35→        model.universes.clear();
    36→        model.domains.clear();
    37→        model.admissible_sets.clear();
    38→        model.transforms.clear();
    39→
    40→        // Always create U0 (root universe)
    41→        let u0 = Universe::root();
    42→        model.universes.insert(u0.id.clone(), u0);
    43→
    44→        // First pass: Create universes and admissible sets from nodes
    45→        Self::sync_nodes(model, repo)?;
    46→
    47→        // Second pass: Create transform functions from edges
    48→        Self::sync_edges(model, repo)?;
    49→
    50→        // Third pass: Create inverse transforms for each projection universe
    51→        Self::create_inverse_transforms(model)?;
    52→
    53→        Ok(())
    54→    }
    55→
    56→    /// Export proof metadata back to repository
    57→    ///
    58→    /// This writes verification results back to the repository as node metadata:
    59→    /// - contradiction_detected: Set for nodes with contradicting specifications
    60→    /// - omission_detected: Set for nodes with omitted domains
    61→    /// - proof_status: proven/refuted/unknown
    62→    /// - proof_timestamp: When the proof was performed
    63→    ///
    64→    /// Returns Ok(()) on success, or Err with error message.
    65→    pub fn export_proof_metadata(model: &UDAFModel, repo: &mut SpecRepository) -> Result<(), String> {
    66→        let timestamp = Utc::now().timestamp().to_string();
    67→
    68→        // Export contradiction metadata
    69→        #[cfg(feature = "z3-solver")]
    70→        {
    71→            let contradictions = model.clone().detect_contradictions();
    72→            for contradiction in contradictions {
    73→                // Mark both contradicting specs
    74→                let spec_a_id = contradiction.spec_a.as_str();
    75→                let spec_b_id = contradiction.spec_b.as_str();
    76→
    77→                repo.update_node_metadata(
    78→                    spec_a_id,
    79→                    "contradiction_detected".to_string(),
    80→                    spec_b_id.to_string(),
    81→                );
    82→                repo.update_node_metadata(
    83→                    spec_a_id,
    84→                    "proof_timestamp".to_string(),
    85→                    timestamp.clone(),
    86→                );
    87→
    88→                repo.update_node_metadata(
    89→                    spec_b_id,
    90→                    "contradiction_detected".to_string(),
    91→                    spec_a_id.to_string(),
    92→                );
    93→                repo.update_node_metadata(
    94→                    spec_b_id,
    95→                    "proof_timestamp".to_string(),
    96→                    timestamp.clone(),
    97→                );
    98→            }
    99→        }
   100→
   101→        // Export omission metadata
   102→        #[cfg(feature = "z3-solver")]
   103→        {
   104→            let omissions = model.clone().detect_omissions();
   105→            for omission in omissions {
   106→                let domain_id = omission.domain_id.as_str();
   107→
   108→                repo.update_node_metadata(
   109→                    domain_id,
   110→                    "omission_detected".to_string(),
   111→                    "true".to_string(),
   112→                );
   113→                repo.update_node_metadata(
   114→                    domain_id,
   115→                    "omission_coverage".to_string(),
   116→                    "detected".to_string(),
   117→                );
   118→                repo.update_node_metadata(
   119→                    domain_id,
   120→                    "proof_timestamp".to_string(),
   121→                    timestamp.clone(),
   122→                );
   123→            }
   124→        }
   125→
   126→        // Export satisfiability results for each specification
   127→        for spec_id in model.admissible_sets.keys() {
   128→            #[cfg(feature = "z3-solver")]
   129→            {
   130→                if let Some(proof) = model.clone().verify_satisfiability(spec_id) {
   131→                    let status = match proof.status {
   132→                        ProofStatus::Proven => "proven",
   133→                        ProofStatus::Refuted => "refuted",
   134→                        ProofStatus::Unknown => "unknown",
   135→                        ProofStatus::Pending => "pending",
   136→                    };
   137→
   138→                    repo.update_node_metadata(
   139→                        spec_id.as_str(),
   140→                        "proof_status".to_string(),
   141→                        status.to_string(),
   142→                    );
   143→                    repo.update_node_metadata(
   144→                        spec_id.as_str(),
   145→                        "proof_timestamp".to_string(),
   146→                        timestamp.clone(),
   147→                    );
   148→                }
   149→            }
   150→
   151→            #[cfg(not(feature = "z3-solver"))]
   152→            {
   153→                // Without Z3, mark as unknown
   154→                repo.update_node_metadata(
   155→                    spec_id.as_str(),
   156→                    "proof_status".to_string(),
   157→                    "unknown".to_string(),
   158→                );
   159→            }
   160→        }
   161→
   162→        Ok(())
   163→    }
   164→
   165→    // ========================================================================
   166→    // Internal sync helpers
   167→    // ========================================================================
   168→
   169→    /// Sync nodes from repository to model
   170→    fn sync_nodes(model: &mut UDAFModel, repo: &SpecRepository) -> Result<(), String> {
   171→        for node in repo.list_nodes(None) {
   172→            let layer = node.formality_layer;
   173→
   174→            // Create universe for this layer if it doesn't exist
   175→            let universe_id = match UniverseId::parse(&format!("U{}", layer)) {
   176→                Ok(id) => id,
   177→                Err(_) => continue,
   178→            };
   179→
   180→            if !model.universes.contains_key(&universe_id) && layer > 0 {
   181→                let (name, description) = Self::universe_names_for_layer(layer);
   182→                model.add_universe(layer, name, description)
   183→                    .map_err(|e| format!("Failed to add universe: {}", e))?;
   184→            }
   185→
   186→            // Parse spec ID
   187→            let spec_id = match SpecId::parse(&node.id) {
   188→                Ok(id) => id,
   189→                Err(_) => continue,
   190→            };
   191→
   192→            // Add spec to universe
   193→            if let Some(universe) = model.universes.get_mut(&universe_id) {
   194→                universe.specifications.insert(spec_id.clone());
   195→            }
   196→
   197→            // Create admissible set for this specification
   198→            let mut admissible_set = AdmissibleSet::new(spec_id.clone(), universe_id.clone());
   199→
   200→            // Extract constraints based on node kind
   201→            match node.kind {
   202→                NodeKind::Constraint => {
   203→                    // For Constraint nodes, create a single explicit constraint
   204→                    let mut meta = ConstraintMetadata::from(node.metadata.clone());
   205→                    meta.insert(MetadataKey::Custom("description".to_string()), node.content.clone());
   206→
   207→                    admissible_set.add_constraint(Constraint {
   208→                        formal: None, // Will be extracted during proof preparation
   209→                        kind: ConstraintKind::Universal,
   210→                        description: Some(node.content.clone()),
   211→                        metadata: Some(ConstraintMetadata::from(node.metadata.clone())),
   212→                        meta: Some(meta),
   213→                    });
   214→                }
   215→                _ => {
   216→                    // For other nodes, extract implicit constraints from natural language
   217→                    let extracted = extract_constraints_from_text(&node.content);
   218→                    for constraint in extracted {
   219→                        admissible_set.add_constraint(constraint);
   220→                    }
   221→                }
   222→            }
   223→
   224→            model.admissible_sets.insert(spec_id.clone(), admissible_set);
   225→
   226→            // Create domain if this is a Domain node
   227→            if node.kind == NodeKind::Domain {
   228→                let domain = Domain::with_id(
   229→                    DomainId::parse(&node.id).unwrap_or_else(|_| DomainId::new()),
   230→                    node.content.clone(),
   231→                    "Domain boundary definition".to_string(),
   232→                    universe_id,
   233→                );
   234→                model.domains.insert(domain.id.clone(), domain);
   235→            }
   236→        }
   237→
   238→        Ok(())
   239→    }
   240→
   241→    /// Sync edges from repository to model
   242→    fn sync_edges(model: &mut UDAFModel, repo: &SpecRepository) -> Result<(), String> {
   243→        for (edge, source_id, target_id) in repo.list_edges(None) {
   244→            // Only process Formalizes and Transform edges
   245→            if !matches!(edge.kind, EdgeKind::Formalizes | EdgeKind::Transform) {
   246→                continue;
   247→            }
   248→
   249→            let source_node = match repo.get_node(source_id) {
   250→                Some(n) => n,
   251→                None => continue,
   252→            };
   253→
   254→            let target_node = match repo.get_node(target_id) {
   255→                Some(n) => n,
   256→                None => continue,
   257→            };
   258→
   259→            // Parse universe IDs
   260→            let source_universe = match UniverseId::parse(&format!("U{}", source_node.formality_layer)) {
   261→                Ok(id) => id,
   262→                Err(_) => continue,
   263→            };
   264→
   265→            let target_universe = match UniverseId::parse(&format!("U{}", target_node.formality_layer)) {
   266→                Ok(id) => id,
   267→                Err(_) => continue,
   268→            };
   269→
   270→            // Create transform function
   271→            let transform = TransformFunction::forward(
   272→                source_universe,
   273→                target_universe,
   274→                format!(
   275→                    "{:?}: {} -> {}",
   276→                    edge.kind,
   277→                    source_node.content.chars().take(30).collect::<String>(),
   278→                    target_node.content.chars().take(30).collect::<String>()
