   282→                },
   283→            );
   284→
   285→            model.transforms.insert(transform.id.clone(), transform);
   286→        }
   287→
   288→        Ok(())
   289→    }
   290→
   291→    /// Create inverse transforms for each projection universe to U0
   292→    fn create_inverse_transforms(model: &mut UDAFModel) -> Result<(), String> {
   293→        let universe_ids: Vec<UniverseId> = model.universes.keys().cloned().collect();
   294→
