   498→    /// Validate all reference integrity across the model
   499→    ///
   500→    /// Checks:
   501→    /// - Universe specifications reference valid SpecIds
   502→    /// - Domain universe_id references valid UniverseIds
   503→    /// - Domain covered_by references valid SpecIds
   504→    /// - Domain subdomains references valid DomainIds
   505→    /// - AdmissibleSet universe_id references valid UniverseIds
   506→    /// - AdmissibleSet contradicts references valid SpecIds
   507→    /// - Transform source/target universes reference valid UniverseIds
   508→    ///
   509→    /// Returns Ok(()) if all references are valid, or Err with details of invalid references
   510→    pub fn validate(&self) -> Result<(), String> {
   511→        let mut errors = Vec::new();
   512→
   513→        // Collect all valid IDs for reference checking
   514→        let valid_universe_ids: HashSet<String> = self.universes.keys()
   515→            .map(|id| id.as_str().to_string())
   516→            .collect();
   517→
   518→        let valid_spec_ids: HashSet<String> = self.admissible_sets.keys()
   519→            .map(|id| id.as_str().to_string())
   520→            .collect();
   521→
   522→        let valid_domain_ids: HashSet<String> = self.domains.keys()
   523→            .map(|id| id.as_str().to_string())
   524→            .collect();
   525→
   526→        // Validate Universe references
   527→        for (universe_id, universe) in &self.universes {
   528→            // Check that all specifications in the universe exist
   529→            let invalid_specs = universe.specifications.check_integrity(&valid_spec_ids);
   530→            if !invalid_specs.is_empty() {
   531→                errors.push(format!(
   532→                    "Universe {} references non-existent specifications: {:?}",
   533→                    universe_id.as_str(),
   534→                    invalid_specs
   535→                ));
   536→            }
   537→        }
   538→
   539→        // Validate Domain references
   540→        for (domain_id, domain) in &self.domains {
   541→            // Check that universe_id exists (try meta first, fall back to old field)
   542→            let universe_id_str = if let Some(meta) = &domain.meta {
   543→                meta.get_str("universe_id").map(|s| s.as_str())
   544→            } else {
   545→                domain.universe_id.as_ref().map(|id| id.as_str())
   546→            };
   547→
   548→            if let Some(uid_str) = universe_id_str
   549→                && !valid_universe_ids.contains(uid_str) {
   550→                    errors.push(format!(
   551→                        "Domain {} references non-existent universe: {}",
   552→                        domain_id.as_str(),
   553→                        uid_str
   554→                    ));
   555→                }
   556→
   557→            // Check that all covered_by specs exist (try proof_data first, fall back to old field)
   558→            let covered_by = if let Some(proof_data) = &domain.proof_data {
   559→                Some(&proof_data.covered_by)
   560→            } else {
   561→                domain.covered_by.as_ref()
   562→            };
   563→
   564→            if let Some(covered_by_set) = covered_by {
   565→                let invalid_specs = covered_by_set.check_integrity(&valid_spec_ids);
   566→                if !invalid_specs.is_empty() {
   567→                    errors.push(format!(
   568→                        "Domain {} references non-existent specifications in covered_by: {:?}",
   569→                        domain_id.as_str(),
   570→                        invalid_specs
   571→                    ));
   572→                }
   573→            }
   574→
   575→            // Check that all subdomains exist (from meta)
   576→            if let Some(meta) = &domain.meta {
   577→                if let Some(_subdomains_str) = meta.get_str("subdomains") {
   578→                    // Note: This is a simplified check; actual subdomain validation would need proper parsing
   579→                    // For now, skip subdomain validation for new structure
   580→                }
   581→            } else if let Some(subdomains) = &domain.subdomains {
   582→                let invalid_domains = subdomains.check_integrity(&valid_domain_ids);
   583→                if !invalid_domains.is_empty() {
   584→                    errors.push(format!(
   585→                        "Domain {} references non-existent subdomains: {:?}",
   586→                        domain_id.as_str(),
   587→                        invalid_domains
   588→                    ));
   589→                }
   590→            }
   591→        }
   592→
   593→        // Validate AdmissibleSet references
   594→        for (spec_id, admissible_set) in &self.admissible_sets {
   595→            // Check that universe_id exists (try meta first, fall back to old field)
   596→            let universe_id_ref = if let Some(meta) = &admissible_set.meta {
   597→                Some(&meta.universe_id)
   598→            } else {
   599→                admissible_set.universe_id.as_ref()
   600→            };
   601→
   602→            if let Some(uid) = universe_id_ref
   603→                && !valid_universe_ids.contains(uid.as_str()) {
   604→                    errors.push(format!(
   605→                        "AdmissibleSet {} references non-existent universe: {}",
   606→                        spec_id.as_str(),
   607→                        uid.as_str()
   608→                    ));
   609→                }
   610→
   611→            // Check that all contradicts references exist (try proof_data first, fall back to old field)
   612→            let contradicts = if let Some(proof_data) = &admissible_set.proof_data {
   613→                Some(&proof_data.contradicts)
   614→            } else {
   615→                admissible_set.contradicts.as_ref()
   616→            };
   617→
   618→            if let Some(contradicts_set) = contradicts {
   619→                let invalid_contradicts = contradicts_set.check_integrity(&valid_spec_ids);
   620→                if !invalid_contradicts.is_empty() {
   621→                    errors.push(format!(
   622→                        "AdmissibleSet {} references non-existent specifications in contradicts: {:?}",
   623→                        spec_id.as_str(),
   624→                        invalid_contradicts
   625→                    ));
   626→                }
   627→            }
   628→        }
   629→
   630→        // Validate Transform references
   631→        for (transform_id, transform) in &self.transforms {
   632→            // Check that source_universe exists
   633→            if !valid_universe_ids.contains(transform.source_universe.as_str()) {
   634→                errors.push(format!(
   635→                    "Transform {} references non-existent source universe: {}",
   636→                    transform_id.as_str(),
   637→                    transform.source_universe.as_str()
   638→                ));
   639→            }
   640→
   641→            // Check that target_universe exists
   642→            if !valid_universe_ids.contains(transform.target_universe.as_str()) {
   643→                errors.push(format!(
   644→                    "Transform {} references non-existent target universe: {}",
   645→                    transform_id.as_str(),
   646→                    transform.target_universe.as_str()
   647→                ));
   648→            }
   649→        }
   650→
   651→        if errors.is_empty() {
   652→            Ok(())
   653→        } else {
   654→            Err(errors.join("\n"))
   655→        }
   656→    }
   657→}
