    37→impl SpecRepository {
    38→    /// Check if inferred spec has sufficient semantic quality
    39→    fn is_high_quality_spec(spec: &InferredSpecification) -> bool {
    40→        let content = &spec.content;
    41→
    42→        // Skip low-quality test assertions that are just code artifacts
    43→        // Examples: "Invariant: g.node_count(), 1", "Invariant: fetched.kind, NodeKind::Assertion"
    44→        if content.starts_with("Invariant: ") {
    45→            // Reject if it contains Rust syntax (it's code, not a spec)
    46→            let rust_syntax_markers = [
    47→                ".iter()", ".any(", ".contains(", ".len()", ".get(",
    48→                "!(", "||", "&&", ">", "<", "==", "!=",
    49→                ".is_empty()", ".starts_with(", ".ends_with(",
    50→                "assert!", "panic!", "unwrap(", "expect(",
    51→                "{}", "[]", "\"{}\"", "format!", "println!"
    52→            ];
    53→            let has_rust_syntax = rust_syntax_markers.iter()
    54→                .any(|marker| content.contains(marker));
    55→
    56→            if has_rust_syntax {
    57→                return false;  // Rust code, not a specification
    58→            }
    59→
    60→            // Also check for semantic keywords (original filter)
    61→            let semantic_keywords = [
    62→                "must", "should", "shall", "require", "ensure", "verify", "validate",
    63→                "detect", "identify", "check", "test verifies", "system", "user",
    64→                "specification", "requirement", "constraint"
    65→            ];
    66→
    67→            let has_semantic_meaning = semantic_keywords.iter()
    68→                .any(|kw| content.to_lowercase().contains(kw));
    69→
    70→            if !has_semantic_meaning {
    71→                // Low-quality test assertion - skip it
    72→                return false;
    73→            }
    74→        }
    75→
    76→        // Skip trivial scenario names that provide no information
    77→        // Examples: "scenario {}", "coverage empty graph", "coverage no tests"
    78→        if content == "scenario {}" || content.trim().is_empty() {
    79→            return false;
    80→        }
    81→
    82→        // Skip test function names that are too short or lack strong semantic value
    83→        // Examples: "coverage empty graph", "empty graph", "no tests", "user login"
    84→        if spec.kind == NodeKind::Scenario || spec.metadata.get("extractor") == Some(&"function_name".to_string()) {
    85→            // Check minimum length (at least 25 characters for descriptive spec)
    86→            if content.len() < 25 {
    87→                return false;
    88→            }
    89→
    90→            // Must have strong semantic keywords (not just "user" or "test")
    91→            let strong_keywords = [
    92→                "must", "should", "shall", "ensure", "verify", "validate",
    93→                "detect", "identify", "check for", "when", "if",
    94→                "specification", "requirement", "constraint", "correctly", "properly",
    95→                "without", "with", "given", "then", "returns", "accepts"
    96→            ];
    97→            let has_strong_semantic = strong_keywords.iter()
    98→                .any(|kw| content.to_lowercase().contains(kw));
    99→
   100→            // Reject if no strong semantics OR if it's just a test name pattern
   101→            let is_trivial_test_name = content.to_lowercase().starts_with("scenario: ") &&
   102→                !has_strong_semantic;
   103→
   104→            if !has_strong_semantic || is_trivial_test_name {
   105→                return false;
   106→            }
   107→        }
   108→
   109→        true
   110→    }
