   437→    /// Infer relationships for a specific node with AI enhancement
   438→    fn infer_relationships_for_node_with_ai(&self, node_id: &str, ai: &crate::AISemantic) -> Vec<EdgeSuggestion> {
   439→        let mut suggestions = Vec::new();
   440→
   441→        let source_node = match self.get_node(node_id) {
   442→            Some(n) => n,
   443→            None => return suggestions,
   444→        };
   445→
   446→        // Get all other nodes
   447→        let all_nodes = self.list_nodes(None);
   448→
   449→        for target_node in all_nodes {
   450→            if target_node.id == node_id {
   451→                continue; // Skip self
   452→            }
   453→
   454→            // Calculate AI-enhanced semantic similarity
   455→            let similarity = self.calculate_semantic_similarity_with_ai(
   456→                &source_node.content,
   457→                source_node.formality_layer,
   458→                &target_node.content,
   459→                target_node.formality_layer,
   460→                ai,
   461→            );
   462→
   463→            // Layer-aware threshold: cross-layer connections need lower threshold
   464→            let threshold = if source_node.formality_layer != target_node.formality_layer {
   465→                0.15  // Cross-layer: proto↔requirement, test↔requirement
   466→            } else {
   467→                0.3   // Same-layer: more strict to avoid noise
   468→            };
   469→
   470→            if similarity < threshold {
   471→                continue; // Too dissimilar
   472→            }
   473→
   474→            // Infer edge kind and confidence based on multiple factors
   475→            if let Some((edge_kind, confidence, explanation)) =
   476→                self.infer_edge_kind(source_node, target_node, similarity)
   477→            {
   478→                suggestions.push(EdgeSuggestion {
   479→                    source_id: node_id.to_string(),
   480→                    target_id: target_node.id.clone(),
   481→                    kind: edge_kind,
   482→                    confidence,
   483→                    explanation,
   484→                });
   485→            }
   486→        }
   487→
   488→        suggestions
   489→    }
