   543→    /// Calculate semantic similarity between two texts (optionally AI-enhanced)
   544→    fn calculate_semantic_similarity(&self, text1: &str, text2: &str) -> f32 {
   545→        // Start with simple keyword-based similarity
   546→        let lower1 = text1.to_lowercase();
   547→        let lower2 = text2.to_lowercase();
   548→
   549→        let words1: std::collections::HashSet<String> =
   550→            lower1.split_whitespace().map(|s| s.to_string()).collect();
   551→        let words2: std::collections::HashSet<String> =
   552→            lower2.split_whitespace().map(|s| s.to_string()).collect();
   553→
   554→        if words1.is_empty() || words2.is_empty() {
   555→            return 0.0;
   556→        }
   557→
   558→        let intersection = words1.intersection(&words2).count();
   559→        let union = words1.union(&words2).count();
   560→
   561→        intersection as f32 / union as f32
   562→    }
   563→
   564→    /// Calculate semantic similarity with AI enhancement for cross-layer comparisons
   565→    fn calculate_semantic_similarity_with_ai(
   566→        &self,
   567→        text1: &str,
   568→        layer1: u8,
   569→        text2: &str,
   570→        layer2: u8,
   571→        ai: &crate::AISemantic,
   572→    ) -> f32 {
   573→        // First try simple similarity
   574→        let simple_sim = self.calculate_semantic_similarity(text1, text2);
   575→
   576→        // For cross-layer comparisons, ALWAYS use AI if available
   577→        // Keyword overlap is meaningless across layers (U0 uses natural language, U2/U3 use technical terms)
   578→        // Example: U0 "system must detect contradictions" ↔ U2 "RPC: DetectContradictions" (overlap ~0.1, semantic ~0.9)
   579→        if layer1 != layer2 {
   580→            if let Some(ai_sim) = ai.semantic_similarity(text1, text2, layer1, layer2) {
   581→                // Trust AI heavily for cross-layer matching
   582→                // Keyword overlap is noise, semantic equivalence is signal
   583→                return simple_sim * 0.2 + ai_sim * 0.8;
   584→            }
   585→            // AI unavailable: fall back to simple similarity (will miss many connections)
   586→            return simple_sim;
   587→        }
   588→
   589→        // Same-layer comparisons: use original conservative logic
   590→        // If similarity is very high (>0.8), trust keyword matching
   591→        if simple_sim > 0.8 {
   592→            return simple_sim;
   593→        }
   594→
   595→        // For moderate similarity (0.4-0.8), use AI to disambiguate
   596→        // This catches same-layer duplicates that keyword matching misses
   597→        if simple_sim >= 0.4
   598→            && let Some(ai_sim) = ai.semantic_similarity(text1, text2, layer1, layer2) {
   599→                // Blend simple and AI similarity (weighted average)
   600→                // Give more weight to AI for disambiguation
   601→                return simple_sim * 0.3 + ai_sim * 0.7;
   602→            }
   603→
   604→        // For very low similarity (<0.4) in same layer, skip AI (too expensive, low probability)
   605→        simple_sim
   606→    }
   607→
   608→    /// Infer edge kind between two nodes
   609→    fn infer_edge_kind(
   610→        &self,
   611→        source: &crate::SpecNodeData,
   612→        target: &crate::SpecNodeData,
   613→        similarity: f32,
   614→    ) -> Option<(EdgeKind, f32, String)> {
   615→        // Rule 1: Synonym - very high similarity, same kind
   616→        // Check this FIRST because it's most specific (highest threshold)
   617→        if similarity > 0.8 && source.kind == target.kind {
   618→            return Some((
   619→                EdgeKind::Synonym,
   620→                similarity * 0.95,
   621→                "Nearly identical content".to_string(),
   622→            ));
   623→        }
   624→
   625→        // Rule 2: Formalizes - same concept, different formality levels
   626→        if similarity > 0.5 && source.formality_layer < target.formality_layer {
   627→            return Some((
   628→                EdgeKind::Formalizes,
   629→                similarity * 0.9,
   630→                format!(
   631→                    "Same concept at different formality levels ({} -> {})",
   632→                    source.formality_layer, target.formality_layer
   633→                ),
   634→            ));
   635→        }
   636→
   637→        // Rule 3: DerivesFrom - assertion derives from constraint
   638→        if similarity > 0.5
   639→            && source.kind == NodeKind::Assertion
   640→            && target.kind == NodeKind::Constraint
   641→        {
   642→            return Some((
   643→                EdgeKind::DerivesFrom,
   644→                similarity * 0.8,
   645→                "Assertion derives from constraint".to_string(),
   646→            ));
   647→        }
   648→
   649→        // Rule 4: Refines - scenario refines constraint, or same kind with high similarity
   650→        if similarity > 0.6 {
   651→            if source.kind == NodeKind::Scenario && target.kind == NodeKind::Constraint {
   652→                return Some((
   653→                    EdgeKind::Refines,
   654→                    similarity * 0.85,
   655→                    "Scenario refines constraint".to_string(),
   656→                ));
   657→            }
   658→            if source.kind == target.kind {
   659→                return Some((
   660→                    EdgeKind::Refines,
   661→                    similarity * 0.9,
   662→                    "Similar specifications (potential refinement)".to_string(),
   663→                ));
   664→            }
   665→        }
   666→
   667→        // Rule 5: Same source file suggests relationship
   668→        if let (Some(src_file), Some(tgt_file)) = (
   669→            source.metadata.get("source_file"),
   670→            target.metadata.get("source_file"),
   671→        )
   672→            && src_file == tgt_file && similarity > 0.4 {
   673→                return Some((
   674→                    EdgeKind::Refines,
   675→                    similarity * 0.7,
   676→                    "Same source file".to_string(),
   677→                ));
   678→            }
   679→
   680→        None
   681→    }
   682→}
