   928→    fn extract_from_docs(
   929→        content: &str,
   930→        file_path: &Path,
   931→    ) -> Result<Vec<InferredSpecification>, String> {
   932→        let mut specs = Vec::new();
   933→        let file_name = file_path.to_string_lossy().to_string();
   934→
   935→        for (line_num, line) in content.lines().enumerate() {
   936→            let trimmed = line.trim();
   937→
   938→            // Match /// or //! doc comments
   939→            if let Some(doc) = trimmed.strip_prefix("///").or_else(|| trimmed.strip_prefix("//!")) {
   940→                let doc_text = doc.trim();
   941→
   942→                // Look for specification keywords
   943→                let (kind, confidence) = if doc_text.contains("must") || doc_text.contains("shall") || doc_text.contains("required") {
   944→                    (NodeKind::Constraint, 0.8)
   945→                } else if doc_text.contains("should") || doc_text.contains("expected") {
   946→                    (NodeKind::Assertion, 0.7)
   947→                } else if doc_text.contains("example") || doc_text.contains("scenario") {
   948→                    (NodeKind::Scenario, 0.6)
   949→                } else {
   950→                    continue; // Not a specification
   951→                };
   952→
   953→                if !doc_text.is_empty() {
   954→                    specs.push(InferredSpecification {
   955→                        content: doc_text.to_string(),
   956→                        kind,
   957→                        confidence,
   958→                        source_file: file_name.clone(),
   959→                        source_line: line_num + 1,
   960→                        formality_layer: 0, // Natural language
   961→                        metadata: HashMap::from([
   962→                            ("doc_comment".to_string(), "true".to_string()),
   963→                            ("extractor".to_string(), "doc".to_string()),
   964→                        ]),
   965→                    });
   966→                }
   967→            }
   968→        }
   969→
   970→        Ok(specs)
   971→    }
   972→
   973→    fn extract_from_panics(
   974→        content: &str,
   975→        file_path: &Path,
   976→    ) -> Result<Vec<InferredSpecification>, String> {
   977→        let mut specs = Vec::new();
   978→        let file_name = file_path.to_string_lossy().to_string();
   979→
   980→        for (line_num, line) in content.lines().enumerate() {
   981→            // Match panic! with message
   982→            if let Some(panic_msg) = Self::extract_panic_message(line) {
   983→                specs.push(InferredSpecification {
   984→                    content: format!("Violation: {}", panic_msg),
   985→                    kind: NodeKind::Constraint,
   986→                    confidence: 0.85,
   987→                    source_file: file_name.clone(),
   988→                    source_line: line_num + 1,
   989→                    formality_layer: 3, // Executable
   990→                    metadata: HashMap::from([
   991→                        ("panic".to_string(), panic_msg.clone()),
   992→                        ("extractor".to_string(), "panic".to_string()),
   993→                    ]),
   994→                });
   995→            }
   996→        }
   997→
   998→        Ok(specs)
   999→    }
  1000→
  1001→    // Helper parsers
  1002→
  1003→    fn extract_fn_name(line: &str) -> Option<String> {
  1004→        let trimmed = line.trim();
  1005→        if trimmed.starts_with("fn ") || trimmed.starts_with("pub fn ") {
  1006→            let after_fn = trimmed.split("fn ").nth(1)?;
  1007→            let name = after_fn.split('(').next()?.trim();
  1008→            Some(name.to_string())
  1009→        } else {
  1010→            None
  1011→        }
  1012→    }
  1013→
  1014→    fn extract_assertion(line: &str) -> Option<String> {
  1015→        let trimmed = line.trim();
  1016→
  1017→        // Match assert!(...), assert_eq!(...), etc.
  1018→        for macro_name in &["assert!", "assert_eq!", "assert_ne!", "debug_assert!"] {
  1019→            if let Some(idx) = trimmed.find(macro_name) {
  1020→                let after_macro = &trimmed[idx + macro_name.len()..];
  1021→                if let Some(start) = after_macro.find('(')
  1022→                    && let Some(end) = after_macro.rfind(')') {
  1023→                        let assertion = &after_macro[start + 1..end];
  1024→                        return Some(assertion.trim().to_string());
  1025→                    }
  1026→            }
  1027→        }
  1028→
  1029→        None
  1030→    }
  1031→
  1032→    fn extract_panic_message(line: &str) -> Option<String> {
  1033→        let trimmed = line.trim();
  1034→
  1035→        if let Some(idx) = trimmed.find("panic!(") {
  1036→            let after_panic = &trimmed[idx + 7..];
  1037→            if let Some(start) = after_panic.find('"')
  1038→                && let Some(end) = after_panic[start + 1..].find('"') {
  1039→                    let message = &after_panic[start + 1..start + 1 + end];
  1040→                    return Some(message.to_string());
  1041→                }
  1042→        }
  1043→
  1044→        None
  1045→    }
  1046→}
