  1168→/// Extract U2 specifications from Protocol Buffer (.proto) files
  1169→pub struct ProtoExtractor;
  1170→
  1171→impl ProtoExtractor {
  1172→    /// Extract RPC interface specifications from proto file
  1173→    pub fn extract(file_path: &Path) -> Result<Vec<InferredSpecification>, String> {
  1174→        let content = std::fs::read_to_string(file_path)
  1175→            .map_err(|e| format!("Failed to read file: {}", e))?;
  1176→
  1177→        let mut specs = Vec::new();
  1178→        let file_name = file_path.to_string_lossy().to_string();
  1179→
  1180→        // Extract RPC definitions
  1181→        let mut current_comment = String::new();
  1182→        for (line_num, line) in content.lines().enumerate() {
  1183→            let trimmed = line.trim();
  1184→
  1185→            // Capture comment lines
  1186→            if trimmed.starts_with("//") {
  1187→                let comment = trimmed.trim_start_matches("//").trim();
  1188→                if !comment.is_empty() {
  1189→                    current_comment = comment.to_string();
  1190→                }
  1191→                continue;
  1192→            }
  1193→
  1194→            // Match RPC definitions: "rpc MethodName(RequestType) returns (ResponseType);"
  1195→            if trimmed.starts_with("rpc ")
  1196→                && let Some(rpc_name) = Self::extract_rpc_name(trimmed) {
  1197→                    let description = if !current_comment.is_empty() {
  1198→                        current_comment.clone()
  1199→                    } else {
  1200→                        // Generate description from RPC name
  1201→                        Self::rpc_name_to_description(&rpc_name)
  1202→                    };
  1203→
  1204→                    specs.push(InferredSpecification {
  1205→                        content: description,
  1206→                        kind: NodeKind::Assertion, // RPC interface is an assertion about behavior
  1207→                        confidence: 0.95, // High confidence - explicitly defined interface
  1208→                        source_file: file_name.clone(),
  1209→                        source_line: line_num + 1,
  1210→                        formality_layer: 2, // U2: Interface/API specification
  1211→                        metadata: HashMap::from([
  1212→                            ("rpc_name".to_string(), rpc_name.clone()),
  1213→                            ("extractor".to_string(), "proto_rpc".to_string()),
  1214→                        ]),
  1215→                    });
  1216→
  1217→                    current_comment.clear();
  1218→                }
  1219→        }
  1220→
  1221→        Ok(specs)
  1222→    }
  1223→
  1224→    fn extract_rpc_name(line: &str) -> Option<String> {
  1225→        // Parse "rpc MethodName(Request) returns (Response);"
  1226→        let after_rpc = line.strip_prefix("rpc ")?.trim();
  1227→        let name = after_rpc.split('(').next()?.trim();
  1228→        Some(name.to_string())
  1229→    }
  1230→
  1231→    fn rpc_name_to_description(rpc_name: &str) -> String {
  1232→        // Convert camelCase/PascalCase to sentence
  1233→        // AddNode -> "RPC: Add node"
  1234→        // DetectContradictions -> "RPC: Detect contradictions"
  1235→        let mut result = String::new();
  1236→        let mut prev_was_lower = false;
  1237→
  1238→        for (i, ch) in rpc_name.chars().enumerate() {
  1239→            if ch.is_uppercase() && prev_was_lower {
  1240→                result.push(' ');
  1241→                result.push(ch.to_lowercase().next().unwrap());
  1242→            } else if i == 0 {
  1243→                // First character stays as-is
  1244→                result.push(ch);
  1245→            } else {
  1246→                result.push(ch.to_lowercase().next().unwrap());
  1247→            }
  1248→            prev_was_lower = ch.is_lowercase();
  1249→        }
  1250→
  1251→        format!("RPC: {}", result)
  1252→    }
  1253→}
