  1467→/// Extract specifications from PHP test files (PHPUnit)
  1468→///
  1469→/// Supports PHPUnit tests with #[Test] attributes:
  1470→/// ```php
  1471→/// #[Test]
  1472→/// public function fixtureReturnsArray(): void {
  1473→///     // test body
  1474→/// }
  1475→/// ```
  1476→pub struct PHPTestExtractor;
  1477→
  1478→impl PHPTestExtractor {
  1479→    /// Extract specifications from PHP test file
  1480→    pub fn extract(file_path: &Path) -> Result<Vec<InferredSpecification>, String> {
  1481→        let content = std::fs::read_to_string(file_path)
  1482→            .map_err(|e| format!("Failed to read file: {}", e))?;
  1483→
  1484→        let mut specs = Vec::new();
  1485→        let file_name = file_path.to_string_lossy().to_string();
  1486→
  1487→        let mut has_test_attribute = false;
  1488→        let mut test_start_line = 0;
  1489→
  1490→        for (line_num, line) in content.lines().enumerate() {
  1491→            let trimmed = line.trim();
  1492→
  1493→            // Detect #[Test] attribute
  1494→            if trimmed == "#[Test]" || trimmed.starts_with("#[Test") {
  1495→                has_test_attribute = true;
  1496→                test_start_line = line_num + 2; // Next line is function declaration
  1497→            } else if has_test_attribute && trimmed.starts_with("public function ") {
  1498→                // Extract test method name
  1499→                if let Some(name) = Self::extract_test_method_name(trimmed) {
  1500→                    // Convert camelCase to human-readable scenario
  1501→                    let scenario_name = Self::convert_camel_case_to_readable(&name);
  1502→
  1503→                    specs.push(InferredSpecification {
  1504→                        content: format!("Test scenario: {}", scenario_name),
  1505→                        kind: NodeKind::Scenario,
  1506→                        confidence: 0.85,
  1507→                        source_file: file_name.clone(),
  1508→                        source_line: test_start_line,
  1509→                        formality_layer: 3, // U3 - Executable test
  1510→                        metadata: HashMap::from([
  1511→                            ("test_method".to_string(), name.clone()),
  1512→                            ("extractor".to_string(), "php_test".to_string()),
  1513→                            ("test_framework".to_string(), "phpunit".to_string()),
  1514→                        ]),
  1515→                    });
  1516→                }
  1517→                has_test_attribute = false;
  1518→            }
  1519→        }
  1520→
  1521→        Ok(specs)
  1522→    }
  1523→
  1524→    /// Extract test method name from PHP function declaration
  1525→    fn extract_test_method_name(line: &str) -> Option<String> {
  1526→        // Match: public function testName(): void
  1527→        let parts: Vec<&str> = line.split_whitespace().collect();
  1528→        for (i, part) in parts.iter().enumerate() {
  1529→            if *part == "function" && i + 1 < parts.len() {
  1530→                let name = parts[i + 1];
  1531→                // Remove parentheses and return type
  1532→                let name = name.split('(').next().unwrap_or(name);
  1533→                return Some(name.to_string());
  1534→            }
  1535→        }
  1536→        None
  1537→    }
  1538→
  1539→    /// Convert camelCase to human-readable format
  1540→    /// Example: "fixtureReturnsArray" → "fixture returns array"
  1541→    fn convert_camel_case_to_readable(name: &str) -> String {
  1542→        let mut result = String::new();
  1543→        let mut prev_lowercase = false;
  1544→
  1545→        for ch in name.chars() {
  1546→            if ch.is_uppercase() {
  1547→                if prev_lowercase {
  1548→                    result.push(' ');
  1549→                }
  1550→                result.push(ch.to_ascii_lowercase());
  1551→                prev_lowercase = false;
  1552→            } else {
  1553→                result.push(ch);
  1554→                prev_lowercase = true;
  1555→            }
  1556→        }
  1557→
  1558→        result
  1559→    }
  1560→}
