     1→/// Transform function identifier with enforced "f_{source}_to_{target}" format
     2→///
     3→/// Valid formats:
     4→/// - "f_U1_to_U0" (inverse mapping)
     5→/// - "f_U1_to_U2" (forward/parallel mapping)
     6→use serde::{Deserialize, Serialize, Deserializer, Serializer};
     7→use std::fmt;
     8→use crate::formal::universe::UniverseId;
     9→use crate::formal::IdError;
    10→
    11→#[derive(Debug, Clone, PartialEq, Eq, Hash)]
    12→pub struct TransformId(String);
    13→
    14→impl TransformId {
    15→    /// Create an inverse mapping ID: f_{source}_to_U0
    16→    pub fn inverse(source: &UniverseId) -> Self {
    17→        Self(format!("f_{}_to_U0", source.as_str()))
    18→    }
    19→
    20→    /// Create a forward/parallel mapping ID: f_{source}_to_{target}
    21→    pub fn forward(source: &UniverseId, target: &UniverseId) -> Self {
    22→        Self(format!("f_{}_to_{}", source.as_str(), target.as_str()))
    23→    }
    24→
    25→    /// Parse from string (validates format)
    26→    pub fn parse(s: &str) -> Result<Self, IdError> {
    27→        if !s.starts_with("f_") {
    28→            return Err(IdError::InvalidFormat(
    29→                format!("Transform ID must start with 'f_', got: {}", s),
    30→            ));
    31→        }
    32→
    33→        if !s.contains("_to_") {
    34→            return Err(IdError::InvalidFormat(
    35→                format!("Transform ID must contain '_to_', got: {}", s),
    36→            ));
    37→        }
    38→
    39→        // Extract source and target
    40→        let parts: Vec<&str> = s.split("_to_").collect();
    41→        if parts.len() != 2 {
    42→            return Err(IdError::InvalidFormat(
    43→                format!("Invalid transform ID format: {}", s),
    44→            ));
    45→        }
    46→
    47→        let source_part = parts[0].strip_prefix("f_").ok_or_else(|| {
    48→            IdError::InvalidFormat(format!("Invalid source in: {}", s))
    49→        })?;
    50→
    51→        // Validate source and target as UniverseIds
    52→        UniverseId::parse(source_part)?;
    53→        UniverseId::parse(parts[1])?;
    54→
    55→        Ok(Self(s.to_string()))
    56→    }
    57→
    58→    /// Get the source universe ID
    59→    pub fn source(&self) -> UniverseId {
    60→        let parts: Vec<&str> = self.0.split("_to_").collect();
    61→        let source_str = parts[0].strip_prefix("f_").unwrap();
    62→        UniverseId::parse(source_str).unwrap()
    63→    }
    64→
    65→    /// Get the target universe ID
    66→    pub fn target(&self) -> UniverseId {
    67→        let parts: Vec<&str> = self.0.split("_to_").collect();
    68→        UniverseId::parse(parts[1]).unwrap()
    69→    }
    70→
    71→    /// Get the string representation
    72→    pub fn as_str(&self) -> &str {
    73→        &self.0
    74→    }
    75→}
    76→
    77→impl fmt::Display for TransformId {
    78→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
    79→        write!(f, "{}", self.0)
    80→    }
    81→}
    82→
    83→impl Serialize for TransformId {
    84→    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    85→    where
    86→        S: Serializer,
    87→    {
    88→        serializer.serialize_str(&self.0)
    89→    }
    90→}
    91→
    92→impl<'de> Deserialize<'de> for TransformId {
    93→    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    94→    where
    95→        D: Deserializer<'de>,
    96→    {
    97→        let s = String::deserialize(deserializer)?;
    98→        TransformId::parse(&s).map_err(serde::de::Error::custom)
    99→    }
   100→}
   101→

