     1→/// UDAF Model: The complete multi-universe specification model
     2→///
     3→/// This is the core data structure that implements the theoretical foundation
     4→/// of specORACLE as described in conversation.md and motivation.md.
     5→use serde::{Deserialize, Serialize};
     6→use std::collections::{HashMap, HashSet};
     7→use crate::formal::*;
     8→use crate::{InferredSpecification, RustExtractor};
     9→use crate::data::SpecRepository;
    10→
    11→#[derive(Debug, Clone, Serialize, Deserialize)]
    12→pub struct UDAFModel {
    13→    /// All universes in the model (keyed by UniverseId)
    14→    #[serde(with = "super::serde_helpers::universe_map_serde")]
    15→    pub universes: HashMap<UniverseId, Universe>,
    16→
    17→    /// All domains across all universes (keyed by DomainId)
    18→    #[serde(with = "super::serde_helpers::domain_map_serde")]
    19→    pub domains: HashMap<DomainId, Domain>,
    20→
    21→    /// All admissible sets (one per specification, keyed by SpecId)
    22→    #[serde(with = "super::serde_helpers::admissible_map_serde")]
    23→    pub admissible_sets: HashMap<SpecId, AdmissibleSet>,
    24→
    25→    /// All transform functions between universes (keyed by TransformId)
    26→    #[serde(with = "super::serde_helpers::transform_map_serde")]
    27→    pub transforms: HashMap<TransformId, TransformFunction>,
    28→
    29→    /// Metadata for extensibility
    30→    pub metadata: Metadata,
    31→
    32→    /// Prover instance for formal verification (not serialized)
    33→    #[serde(skip)]
    34→    #[cfg(feature = "z3-solver")]
    35→    prover: Prover,
    36→}
    37→
    38→impl UDAFModel {
    39→    pub fn new() -> Self {
    40→        let mut model = Self {
    41→            universes: HashMap::new(),
    42→            domains: HashMap::new(),
    43→            admissible_sets: HashMap::new(),
    44→            transforms: HashMap::new(),
    45→            metadata: Metadata::new(),
    46→            #[cfg(feature = "z3-solver")]
    47→            prover: Prover::new(),
    48→        };
    49→
    50→        // Always create U0 (root universe)
    51→        let u0 = Universe::root();
    52→        model.universes.insert(u0.id.clone(), u0);
    53→
    54→        model
    55→    }
    56→
    57→    /// Add a projection universe (U1, U2, etc.)
    58→    ///
    59→    /// Returns the universe ID or an error if layer is invalid
    60→    pub fn add_universe(&mut self, layer: u8, name: String, description: String) -> Result<UniverseId, IdError> {
    61→        let universe = Universe::projection(layer, name, description)?;
    62→        let id = universe.id.clone();
    63→        self.universes.insert(id.clone(), universe);
    64→        Ok(id)
    65→    }
    66→
    67→    /// Add a domain to a universe
    68→    pub fn add_domain(&mut self, domain: Domain) -> DomainId {
    69→        let id = domain.id.clone();
    70→        self.domains.insert(id.clone(), domain);
    71→        id
    72→    }
    73→
    74→    /// Add an admissible set for a specification
    75→    pub fn add_admissible_set(&mut self, admissible_set: AdmissibleSet) -> SpecId {
    76→        let id = admissible_set.spec_id.clone();
    77→        self.admissible_sets.insert(id.clone(), admissible_set);
    78→        id
    79→    }
    80→
    81→    /// Add a transform function
    82→    pub fn add_transform(&mut self, transform: TransformFunction) -> TransformId {
    83→        let id = transform.id.clone();
    84→        self.transforms.insert(id.clone(), transform);
    85→        id
    86→    }
    87→
    88→    /// Construct U0 from all projection universes via inverse mappings
    89→    ///
    90→    /// U0 = f₀₁⁻¹(U1) ∪ f₀₂⁻¹(U2) ∪ ... ∪ f₀ₙ⁻¹(UN)
    91→    ///
    92→    /// This is the core operation that realizes the theoretical model.
    93→    /// Returns the newly extracted InferredSpecification objects that should be ingested into the graph.
    94→    pub fn construct_u0(&mut self, graph: &SpecRepository) -> Result<Vec<InferredSpecification>, String> {
    95→        // Collect all newly extracted specifications from projection universes
    96→        let mut newly_created_specs = Vec::new();
    97→
    98→        // For each projection universe (U1, U2, U3...)
    99→        for universe_id in self.universes.keys() {
   100→            if universe_id.layer() == 0 {
   101→                continue;  // Skip U0 itself
   102→            }
   103→
   104→            // Find the inverse transform for this universe
   105→            let inverse_transform_id = TransformId::inverse(universe_id);
   106→
   107→            if let Some(transform) = self.transforms.get(&inverse_transform_id) {
   108→                // Execute the transform strategy to extract/map specifications
   109→                let extracted_specs = self.execute_transform(transform, graph)?;
   110→                newly_created_specs.extend(extracted_specs);
   111→            }
   112→        }
   113→
   114→        Ok(newly_created_specs)
   115→    }
   116→
   117→    /// Execute a transform strategy to extract specifications
   118→    fn execute_transform(
   119→        &self,
   120→        transform: &TransformFunction,
   121→        graph: &SpecRepository,
   122→    ) -> Result<Vec<InferredSpecification>, String> {
   123→        match &transform.strategy {
   124→            TransformStrategy::ASTAnalysis { language, extractor_config } => {
   125→                // Execute AST analysis for the specified language
   126→                if language == "rust" {
   127→                    self.execute_rust_ast_analysis(extractor_config, graph)
   128→                } else {
   129→                    Err(format!("Unsupported language: {}", language))
   130→                }
   131→            }
   132→            TransformStrategy::Manual { description: _ } => {
   133→                // Manual transforms don't auto-execute
   134→                Ok(Vec::new())
   135→            }
   136→            _ => {
   137→                // Other strategies not yet implemented
   138→                Ok(Vec::new())
   139→            }
   140→        }
   141→    }
   142→
   143→    /// Execute Rust AST analysis to extract specifications from code
   144→    fn execute_rust_ast_analysis(
   145→        &self,
   146→        config: &HashMap<String, String>,
   147→        graph: &SpecRepository,
   148→    ) -> Result<Vec<InferredSpecification>, String> {
   149→        use std::path::Path;
   150→
   151→        // Get source files from config or find them in graph metadata
   152→        let source_files = self.find_rust_source_files(config, graph)?;
   153→
   154→        let mut extracted_specs = Vec::new();
   155→
   156→        for file_path in source_files {
   157→            let path = Path::new(&file_path);
   158→
   159→            // Extract specifications using RustExtractor
   160→            match RustExtractor::extract(path) {
   161→                Ok(inferred_specs) => {
   162→                    // Filter by confidence threshold from config
   163→                    let min_confidence = config
   164→                        .get("min_confidence")
   165→                        .and_then(|s| s.parse::<f32>().ok())
   166→                        .unwrap_or(0.7);
   167→
   168→                    for spec in inferred_specs {
   169→                        if spec.confidence >= min_confidence {
   170→                            // Return the actual InferredSpecification objects
   171→                            // These will be ingested into the graph
   172→                            extracted_specs.push(spec);
   173→                        }
   174→                    }
   175→                }
   176→                Err(e) => {
   177→                    eprintln!("Warning: Failed to extract from {}: {}", file_path, e);
   178→                }
   179→            }
   180→        }
   181→
   182→        Ok(extracted_specs)
   183→    }
   184→
   185→    /// Find Rust source files to analyze from config or graph metadata
   186→    fn find_rust_source_files(
   187→        &self,
   188→        config: &HashMap<String, String>,
   189→        graph: &SpecRepository,
   190→    ) -> Result<Vec<String>, String> {
   191→        // If source_files specified in config, use those
   192→        if let Some(files_str) = config.get("source_files") {
   193→            return Ok(files_str.split(',').map(|s| s.trim().to_string()).collect());
   194→        }
   195→
   196→        // Otherwise, find source files from graph nodes with source_file metadata
   197→        let mut source_files = HashSet::new();
   198→        for node in graph.list_nodes(None) {
   199→            // Note: graph nodes still use HashMap<String, String> for metadata
   200→            // so we use the string key directly
   201→            if let Some(source_file) = node.metadata.get(MetadataKey::SourceFile.as_str())
   202→                && source_file.ends_with(".rs") {
   203→                    source_files.insert(source_file.clone());
   204→                }
   205→        }
   206→
   207→        if source_files.is_empty() {
   208→            Err("No source files found in config or graph metadata".to_string())
   209→        } else {
   210→            Ok(source_files.into_iter().collect())
   211→        }
   212→    }
   213→
   214→    /// Detect contradictions: A1 ∩ A2 = ∅
   215→    ///
   216→    /// Returns pairs of admissible sets that are mutually exclusive.
   217→    /// This method uses the Prover to perform formal verification.
   218→    #[cfg(feature = "z3-solver")]
   219→    pub fn detect_contradictions(&mut self) -> Vec<super::verify::Contradiction> {
   220→        self.detect_contradictions_with_prover(&mut self.prover.clone())
   221→    }
   222→
   223→    /// Verify satisfiability of a specification: ∃x. x ∈ A
   224→    ///
   225→    /// Attempts to prove that at least one implementation satisfies the spec.
   226→    /// Uses Z3 SMT solver for formal verification.
   227→    #[cfg(feature = "z3-solver")]
   228→    pub fn verify_satisfiability(&mut self, spec_id: &SpecId) -> Option<Proof> {
   229→        if let Some(spec) = self.admissible_sets.get(spec_id) {
   230→            Some(self.prover.prove_satisfiability(spec))
   231→        } else {
   232→            None
   233→        }
   234→    }
   235→
   236→    /// Prove consistency between two specifications
   237→    ///
   238→    /// Wrapper method that uses the embedded Prover to check consistency.
   239→    #[cfg(feature = "z3-solver")]
   240→    pub fn prove_consistency(&mut self, spec_a_id: &SpecId, spec_b_id: &SpecId) -> Option<Proof> {
   241→        if let (Some(spec_a), Some(spec_b)) = (
   242→            self.admissible_sets.get(spec_a_id),
   243→            self.admissible_sets.get(spec_b_id),
   244→        ) {
   245→            Some(self.prover.prove_consistency(spec_a, spec_b))
   246→        } else {
   247→            None
   248→        }
   249→    }
   250→
   251→    /// Detect omissions: Domains without coverage
   252→    ///
   253→    /// Returns domains where D \ D_S ≠ ∅ (intended domain minus specified domain).
   254→    /// This method uses the Prover to perform formal verification.
   255→    #[cfg(feature = "z3-solver")]
   256→    pub fn detect_omissions(&mut self) -> Vec<super::verify::Omission> {
   257→        self.detect_omissions_with_prover(&mut self.prover.clone())
   258→    }
   259→
   260→    /// Extract constraints from natural language text
   261→    ///
   262→    /// Parses specification text to identify implicit constraints like:
   263→    /// - "at least N" → minimum constraint
   264→    /// - "at most N" → maximum constraint
   265→    /// - "must be" / "must not be" → boolean constraints
   266→    /// - "between X and Y" → range constraints
   267→    ///
   268→    /// Returns a vector of extracted constraints.
   269→    ///
   270→    /// NOTE: This method now delegates to the consolidated implementation in constraint.rs
   271→    #[allow(dead_code)]
   272→    pub(crate) fn extract_constraints_from_text(&self, text: &str) -> Vec<Constraint> {
   273→        super::constraint::extract_constraints_from_text(text)
   274→    }
   275→
   276→    /// DEPRECATED: Old implementation - use extract_constraints_from_text instead
   277→    #[allow(dead_code)]
   278→    fn extract_constraints_from_text_old(&self, text: &str) -> Vec<Constraint> {
   279→        let mut constraints = Vec::new();
   280→        let lower_text = text.to_lowercase();
   281→
   282→        // Pattern 1: "at least N"
   283→        if let Some(min_value) = self.extract_numeric_value(&lower_text, "at least") {
   284→            let mut meta = ConstraintMetadata::new();
   285→            meta.set_pattern("at_least".to_string());
   286→            meta.set_value(min_value.to_string());
   287→            meta.set_source(text.to_string());
   288→
   289→            let description_text = format!("Minimum value: {}", min_value);
   290→            let mut meta_with_desc = meta.clone();
   291→            meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   292→
   293→            constraints.push(Constraint {
   294→                // Layer 2: Proof data
   295→                formal: Some(format!(">= {}", min_value)),
   296→                kind: ConstraintKind::Universal,
   297→                // OLD fields (for compatibility)
   298→                description: Some(description_text),
   299→                metadata: Some(meta),
   300→                // NEW field (preferred)
   301→                meta: Some(meta_with_desc),
   302→            });
   303→        }
   304→
   305→        // Pattern 2: "at most N"
   306→        if let Some(max_value) = self.extract_numeric_value(&lower_text, "at most") {
   307→            let mut meta = ConstraintMetadata::new();
   308→            meta.set_pattern("at_most".to_string());
   309→            meta.set_value(max_value.to_string());
   310→            meta.set_source(text.to_string());
   311→
   312→            let description_text = format!("Maximum value: {}", max_value);
   313→            let mut meta_with_desc = meta.clone();
   314→            meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   315→
   316→            constraints.push(Constraint {
   317→                formal: Some(format!("<= {}", max_value)),
   318→                kind: ConstraintKind::Universal,
   319→                description: Some(description_text),
   320→                metadata: Some(meta),
   321→                meta: Some(meta_with_desc),
   322→            });
   323→        }
   324→
   325→        // Pattern 3: "minimum N" / "minimum of N"
   326→        if let Some(min_value) = self.extract_numeric_value(&lower_text, "minimum") {
   327→            let mut meta = ConstraintMetadata::new();
   328→            meta.set_pattern("minimum".to_string());
   329→            meta.set_value(min_value.to_string());
   330→            meta.set_source(text.to_string());
   331→
   332→            let description_text = format!("Minimum value: {}", min_value);
   333→            let mut meta_with_desc = meta.clone();
   334→            meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   335→
   336→            constraints.push(Constraint {
   337→                formal: Some(format!(">= {}", min_value)),
   338→                kind: ConstraintKind::Universal,
   339→                description: Some(description_text),
   340→                metadata: Some(meta),
   341→                meta: Some(meta_with_desc),
   342→            });
   343→        }
   344→
   345→        // Pattern 4: "maximum N" / "maximum of N"
   346→        if let Some(max_value) = self.extract_numeric_value(&lower_text, "maximum") {
   347→            let mut meta = ConstraintMetadata::new();
   348→            meta.set_pattern("maximum".to_string());
   349→            meta.set_value(max_value.to_string());
   350→            meta.set_source(text.to_string());
   351→
   352→            let description_text = format!("Maximum value: {}", max_value);
   353→            let mut meta_with_desc = meta.clone();
   354→            meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   355→
   356→            constraints.push(Constraint {
   357→                formal: Some(format!("<= {}", max_value)),
   358→                kind: ConstraintKind::Universal,
   359→                description: Some(description_text),
   360→                metadata: Some(meta),
   361→                meta: Some(meta_with_desc),
   362→            });
   363→        }
   364→
   365→        // Pattern 5: "exactly N"
   366→        if let Some(exact_value) = self.extract_numeric_value(&lower_text, "exactly") {
   367→            let mut meta = ConstraintMetadata::new();
   368→            meta.set_pattern("exactly".to_string());
   369→            meta.set_value(exact_value.to_string());
   370→            meta.set_source(text.to_string());
   371→
   372→            let description_text = format!("Exact value: {}", exact_value);
   373→            let mut meta_with_desc = meta.clone();
   374→            meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   375→
   376→            constraints.push(Constraint {
   377→                formal: Some(format!("== {}", exact_value)),
   378→                kind: ConstraintKind::Universal,
   379→                description: Some(description_text),
   380→                metadata: Some(meta),
   381→                meta: Some(meta_with_desc),
   382→            });
   383→        }
   384→
   385→        // Pattern 6: "between X and Y"
   386→        if let Some((min, max)) = self.extract_range(&lower_text) {
   387→            let mut meta = ConstraintMetadata::new();
   388→            meta.set_pattern("range".to_string());
   389→            meta.set_min(min.to_string());
   390→            meta.set_max(max.to_string());
   391→            meta.set_source(text.to_string());
   392→
   393→            let description_text = format!("Range: {} to {}", min, max);
   394→            let mut meta_with_desc = meta.clone();
   395→            meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   396→
   397→            constraints.push(Constraint {
   398→                formal: Some(format!(">= {} && <= {}", min, max)),
   399→                kind: ConstraintKind::Universal,
   400→                description: Some(description_text),
   401→                metadata: Some(meta),
   402→                meta: Some(meta_with_desc),
   403→            });
   404→        }
   405→
   406→        // Pattern 7: "must be" (boolean requirement)
   407→        if lower_text.contains("must be") && !lower_text.contains("at least") && !lower_text.contains("at most") {
   408→            // Extract what must be
   409→            if let Some(pos) = lower_text.find("must be") {
   410→                let after = &text[pos + 7..].trim();
   411→                if !after.is_empty() {
   412→                    let mut meta = ConstraintMetadata::new();
   413→                    meta.set_pattern("must_be".to_string());
   414→                    meta.set_value(after.to_string());
   415→                    meta.set_source(text.to_string());
   416→
   417→                    let description_text = format!("Required: {}", after);
   418→                    let mut meta_with_desc = meta.clone();
   419→                    meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   420→
   421→                    constraints.push(Constraint {
   422→                        formal: Some(format!("== {}", after)),
   423→                        kind: ConstraintKind::Universal,
   424→                        description: Some(description_text),
   425→                        metadata: Some(meta),
   426→                        meta: Some(meta_with_desc),
   427→                    });
   428→                }
   429→            }
   430→        }
   431→
   432→        // Pattern 8: "must not be" / "cannot be" (boolean prohibition)
   433→        if lower_text.contains("must not") || lower_text.contains("cannot be") {
   434→            let pattern = if lower_text.contains("must not") { "must not" } else { "cannot be" };
   435→            if let Some(pos) = lower_text.find(pattern) {
   436→                let after = &text[pos + pattern.len()..].trim();
   437→                if !after.is_empty() {
   438→                    let mut meta = ConstraintMetadata::new();
   439→                    meta.set_pattern("must_not_be".to_string());
   440→                    meta.set_value(after.to_string());
   441→                    meta.set_source(text.to_string());
   442→
   443→                    let description_text = format!("Forbidden: {}", after);
   444→                    let mut meta_with_desc = meta.clone();
   445→                    meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   446→
   447→                    constraints.push(Constraint {
   448→                        formal: Some(format!("!= {}", after)),
   449→                        kind: ConstraintKind::Universal,
   450→                        description: Some(description_text),
   451→                        metadata: Some(meta),
   452→                        meta: Some(meta_with_desc),
   453→                    });
   454→                }
   455→            }
   456→        }
   457→
   458→        constraints
   459→    }
   460→
   461→    /// Extract numeric value after a keyword
   462→    fn extract_numeric_value(&self, text: &str, keyword: &str) -> Option<i64> {
   463→        if let Some(pos) = text.find(keyword) {
   464→            let after = &text[pos + keyword.len()..];
   465→            for word in after.split_whitespace() {
   466→                if let Ok(n) = word.trim_matches(|c: char| !c.is_numeric()).parse::<i64>() {
   467→                    return Some(n);
   468→                }
   469→            }
   470→        }
   471→        None
   472→    }
   473→
   474→    /// Extract range from "between X and Y" pattern
   475→    fn extract_range(&self, text: &str) -> Option<(i64, i64)> {
   476→        if let Some(pos) = text.find("between") {
   477→            let after = &text[pos + 7..];
   478→            let parts: Vec<&str> = after.split("and").collect();
   479→            if parts.len() >= 2 {
   480→                let min = self.extract_first_number(parts[0])?;
   481→                let max = self.extract_first_number(parts[1])?;
   482→                return Some((min, max));
   483→            }
   484→        }
   485→        None
   486→    }
   487→
   488→    /// Extract first number from string
   489→    fn extract_first_number(&self, s: &str) -> Option<i64> {
   490→        for word in s.split_whitespace() {
   491→            if let Ok(n) = word.trim_matches(|c: char| !c.is_numeric()).parse::<i64>() {
   492→                return Some(n);
   493→            }
   494→        }
   495→        None
   496→    }
   497→
   498→    /// Validate all reference integrity across the model
   499→    ///
   500→    /// Checks:
   501→    /// - Universe specifications reference valid SpecIds
   502→    /// - Domain universe_id references valid UniverseIds
   503→    /// - Domain covered_by references valid SpecIds
   504→    /// - Domain subdomains references valid DomainIds
   505→    /// - AdmissibleSet universe_id references valid UniverseIds
   506→    /// - AdmissibleSet contradicts references valid SpecIds
   507→    /// - Transform source/target universes reference valid UniverseIds
   508→    ///
   509→    /// Returns Ok(()) if all references are valid, or Err with details of invalid references
   510→    pub fn validate(&self) -> Result<(), String> {
   511→        let mut errors = Vec::new();
   512→
   513→        // Collect all valid IDs for reference checking
   514→        let valid_universe_ids: HashSet<String> = self.universes.keys()
   515→            .map(|id| id.as_str().to_string())
   516→            .collect();
   517→
   518→        let valid_spec_ids: HashSet<String> = self.admissible_sets.keys()
   519→            .map(|id| id.as_str().to_string())
   520→            .collect();
   521→
   522→        let valid_domain_ids: HashSet<String> = self.domains.keys()
   523→            .map(|id| id.as_str().to_string())
   524→            .collect();
   525→
   526→        // Validate Universe references
   527→        for (universe_id, universe) in &self.universes {
   528→            // Check that all specifications in the universe exist
   529→            let invalid_specs = universe.specifications.check_integrity(&valid_spec_ids);
   530→            if !invalid_specs.is_empty() {
   531→                errors.push(format!(
   532→                    "Universe {} references non-existent specifications: {:?}",
   533→                    universe_id.as_str(),
   534→                    invalid_specs
   535→                ));
   536→            }
   537→        }
   538→
   539→        // Validate Domain references
   540→        for (domain_id, domain) in &self.domains {
   541→            // Check that universe_id exists (try meta first, fall back to old field)
   542→            let universe_id_str = if let Some(meta) = &domain.meta {
   543→                meta.get_str("universe_id").map(|s| s.as_str())
   544→            } else {
   545→                domain.universe_id.as_ref().map(|id| id.as_str())
   546→            };
   547→
   548→            if let Some(uid_str) = universe_id_str
   549→                && !valid_universe_ids.contains(uid_str) {
   550→                    errors.push(format!(
   551→                        "Domain {} references non-existent universe: {}",
   552→                        domain_id.as_str(),
   553→                        uid_str
   554→                    ));
   555→                }
   556→
   557→            // Check that all covered_by specs exist (try proof_data first, fall back to old field)
   558→            let covered_by = if let Some(proof_data) = &domain.proof_data {
   559→                Some(&proof_data.covered_by)
   560→            } else {
   561→                domain.covered_by.as_ref()
   562→            };
   563→
   564→            if let Some(covered_by_set) = covered_by {
   565→                let invalid_specs = covered_by_set.check_integrity(&valid_spec_ids);
   566→                if !invalid_specs.is_empty() {
   567→                    errors.push(format!(
   568→                        "Domain {} references non-existent specifications in covered_by: {:?}",
   569→                        domain_id.as_str(),
   570→                        invalid_specs
   571→                    ));
   572→                }
   573→            }
   574→
   575→            // Check that all subdomains exist (from meta)
   576→            if let Some(meta) = &domain.meta {
   577→                if let Some(_subdomains_str) = meta.get_str("subdomains") {
   578→                    // Note: This is a simplified check; actual subdomain validation would need proper parsing
   579→                    // For now, skip subdomain validation for new structure
   580→                }
   581→            } else if let Some(subdomains) = &domain.subdomains {
   582→                let invalid_domains = subdomains.check_integrity(&valid_domain_ids);
   583→                if !invalid_domains.is_empty() {
   584→                    errors.push(format!(
   585→                        "Domain {} references non-existent subdomains: {:?}",
   586→                        domain_id.as_str(),
   587→                        invalid_domains
   588→                    ));
   589→                }
   590→            }
   591→        }
   592→
   593→        // Validate AdmissibleSet references
   594→        for (spec_id, admissible_set) in &self.admissible_sets {
   595→            // Check that universe_id exists (try meta first, fall back to old field)
   596→            let universe_id_ref = if let Some(meta) = &admissible_set.meta {
   597→                Some(&meta.universe_id)
   598→            } else {
   599→                admissible_set.universe_id.as_ref()
   600→            };
   601→
   602→            if let Some(uid) = universe_id_ref
   603→                && !valid_universe_ids.contains(uid.as_str()) {
   604→                    errors.push(format!(
   605→                        "AdmissibleSet {} references non-existent universe: {}",
   606→                        spec_id.as_str(),
   607→                        uid.as_str()
   608→                    ));
   609→                }
   610→
   611→            // Check that all contradicts references exist (try proof_data first, fall back to old field)
   612→            let contradicts = if let Some(proof_data) = &admissible_set.proof_data {
   613→                Some(&proof_data.contradicts)
   614→            } else {
   615→                admissible_set.contradicts.as_ref()
   616→            };
   617→
   618→            if let Some(contradicts_set) = contradicts {
   619→                let invalid_contradicts = contradicts_set.check_integrity(&valid_spec_ids);
   620→                if !invalid_contradicts.is_empty() {
   621→                    errors.push(format!(
   622→                        "AdmissibleSet {} references non-existent specifications in contradicts: {:?}",
   623→                        spec_id.as_str(),
   624→                        invalid_contradicts
   625→                    ));
   626→                }
   627→            }
   628→        }
   629→
   630→        // Validate Transform references
   631→        for (transform_id, transform) in &self.transforms {
   632→            // Check that source_universe exists
   633→            if !valid_universe_ids.contains(transform.source_universe.as_str()) {
   634→                errors.push(format!(
   635→                    "Transform {} references non-existent source universe: {}",
   636→                    transform_id.as_str(),
   637→                    transform.source_universe.as_str()
   638→                ));
   639→            }
   640→
   641→            // Check that target_universe exists
   642→            if !valid_universe_ids.contains(transform.target_universe.as_str()) {
   643→                errors.push(format!(
   644→                    "Transform {} references non-existent target universe: {}",
   645→                    transform_id.as_str(),
   646→                    transform.target_universe.as_str()
   647→                ));
   648→            }
   649→        }
   650→
   651→        if errors.is_empty() {
   652→            Ok(())
   653→        } else {
   654→            Err(errors.join("\n"))
   655→        }
   656→    }
   657→}
