     1→/// Domain: The region that a specification actually covers
     2→///
     3→/// D represents "what this specification is about" - the subset of the universe
     4→/// that the specification intends to govern.
     5→///
     6→/// Gap detection: D \ D_S (intended domain minus actually specified domain)
     7→///
     8→/// ## 3-Layer Structure (Phase A: Minimization)
     9→/// - Layer 1: Identifier (`id`)
    10→/// - Layer 2: Proof Data (`proof_data`) - formal domain boundaries, coverage tracking
    11→/// - Layer 3: Metadata (`meta`) - human-readable info, organizational structure
    12→use serde::{Deserialize, Serialize};
    13→use super::{DomainId, DomainMetadata, DomainSet};
    14→use crate::formal::universe::UniverseId;
    15→use crate::formal::constraint::Constraint;
    16→use crate::formal::{SpecSet, MetadataKey};
    17→
    18→#[derive(Debug, Clone, Serialize, Deserialize)]
    19→pub struct Domain {
    20→    /// Layer 1: Unique identifier for this domain
    21→    pub id: DomainId,
    22→
    23→    // OLD FIELDS (deprecated, for migration compatibility)
    24→    /// Human-readable name (DEPRECATED: use meta.name)
    25→    #[serde(skip_serializing_if = "Option::is_none")]
    26→    pub name: Option<String>,
    27→
    28→    /// What this domain covers (DEPRECATED: use meta.description)
    29→    #[serde(skip_serializing_if = "Option::is_none")]
    30→    pub description: Option<String>,
    31→
    32→    /// The universe this domain belongs to (DEPRECATED: use meta.universe_id)
    33→    #[serde(skip_serializing_if = "Option::is_none")]
    34→    pub universe_id: Option<UniverseId>,
    35→
    36→    /// Specifications that cover this domain (DEPRECATED: use proof_data.covered_by)
    37→    #[serde(skip_serializing_if = "Option::is_none")]
    38→    pub covered_by: Option<SpecSet>,
    39→
    40→    /// Sub-domains (DEPRECATED: use meta.subdomains)
    41→    #[serde(skip_serializing_if = "Option::is_none")]
    42→    pub subdomains: Option<DomainSet>,
    43→
    44→    /// Metadata for extensibility (DEPRECATED: use meta)
    45→    #[serde(skip_serializing_if = "Option::is_none")]
    46→    pub metadata: Option<DomainMetadata>,
    47→
    48→    // NEW FIELDS (preferred)
    49→    /// Layer 2: Proof-essential data (constraints, coverage)
    50→    #[serde(skip_serializing_if = "Option::is_none")]
    51→    pub proof_data: Option<DomainProofData>,
    52→
    53→    /// Layer 3: Metadata (name, description, organizational structure)
    54→    #[serde(skip_serializing_if = "Option::is_none")]
    55→    pub meta: Option<DomainMetadata>,
    56→}
    57→
    58→/// Layer 2: Proof-essential data for Domain
    59→///
    60→/// Contains only the data needed for formal verification and proofs.
    61→/// The Prover should only access this layer, never metadata.
    62→#[derive(Debug, Clone, Serialize, Deserialize)]
    63→pub struct DomainProofData {
    64→    /// Formal domain boundary constraints (NEW: for completeness proofs)
    65→    /// When empty: Domain is not formalized (graceful degradation)
    66→    /// When present: Enables formal proofs about domain coverage (D ⊆ D_S)
    67→    pub constraints: Vec<Constraint>,
    68→
    69→    /// Specifications that cover this domain (for completeness checking)
    70→    pub covered_by: SpecSet,
    71→}
    72→
    73→impl DomainProofData {
    74→    pub fn new() -> Self {
    75→        Self {
    76→            constraints: Vec::new(),
    77→            covered_by: SpecSet::new(),
    78→        }
    79→    }
    80→
    81→    /// Add a formal constraint to the domain boundary
    82→    pub fn add_constraint(&mut self, constraint: Constraint) {
    83→        self.constraints.push(constraint);
    84→    }
    85→
    86→    /// Check if domain is formalized (has constraints)
    87→    pub fn is_formalized(&self) -> bool {
    88→        !self.constraints.is_empty()
    89→    }
    90→}
    91→
    92→impl Default for DomainProofData {
    93→    fn default() -> Self {
    94→        Self::new()
    95→    }
    96→}
    97→
    98→impl Domain {
    99→    /// Create a new domain with generated ID (NEW: uses 3-layer structure)
   100→    pub fn new(name: String, description: String, universe_id: UniverseId) -> Self {
   101→        let mut meta = DomainMetadata::new();
   102→        meta.insert(MetadataKey::Custom("name".to_string()), name.clone());
   103→        meta.insert(MetadataKey::Custom("description".to_string()), description.clone());
   104→        meta.insert(MetadataKey::Custom("universe_id".to_string()), universe_id.as_str().to_string());
   105→
   106→        Self {
   107→            id: DomainId::new(),
   108→            // OLD fields (populated for compatibility)
   109→            name: Some(name),
   110→            description: Some(description),
   111→            universe_id: Some(universe_id),
   112→            covered_by: Some(SpecSet::new()),
   113→            subdomains: Some(DomainSet::new()),
   114→            metadata: Some(DomainMetadata::new()),
   115→            // NEW fields (preferred)
   116→            proof_data: Some(DomainProofData::new()),
   117→            meta: Some(meta),
   118→        }
   119→    }
   120→
   121→    /// Create a domain with specific ID (for loading from storage)
   122→    pub fn with_id(id: DomainId, name: String, description: String, universe_id: UniverseId) -> Self {
   123→        let mut meta = DomainMetadata::new();
   124→        meta.insert(MetadataKey::Custom("name".to_string()), name.clone());
   125→        meta.insert(MetadataKey::Custom("description".to_string()), description.clone());
   126→        meta.insert(MetadataKey::Custom("universe_id".to_string()), universe_id.as_str().to_string());
   127→
   128→        Self {
   129→            id,
   130→            // OLD fields (populated for compatibility)
   131→            name: Some(name),
   132→            description: Some(description),
   133→            universe_id: Some(universe_id),
   134→            covered_by: Some(SpecSet::new()),
   135→            subdomains: Some(DomainSet::new()),
   136→            metadata: Some(DomainMetadata::new()),
   137→            // NEW fields (preferred)
   138→            proof_data: Some(DomainProofData::new()),
   139→            meta: Some(meta),
   140→        }
   141→    }
   142→
   143→    /// Add a formal constraint to the domain boundary
   144→    pub fn add_constraint(&mut self, constraint: Constraint) {
   145→        if let Some(proof_data) = &mut self.proof_data {
   146→            proof_data.add_constraint(constraint);
   147→        }
   148→    }
   149→
   150→    /// Get proof data (for Prover access)
   151→    pub fn get_proof_data(&self) -> Option<&DomainProofData> {
   152→        self.proof_data.as_ref()
   153→    }
   154→
   155→    /// Get mutable proof data
   156→    pub fn get_proof_data_mut(&mut self) -> Option<&mut DomainProofData> {
   157→        self.proof_data.as_mut()
   158→    }
   159→
   160→    /// Check if this domain has any coverage gaps
   161→    /// Tries new field first, falls back to old field
   162→    pub fn has_gaps(&self) -> bool {
   163→        if let Some(proof_data) = &self.proof_data {
   164→            proof_data.covered_by.is_empty()
   165→        } else if let Some(covered_by) = &self.covered_by {
   166→            covered_by.is_empty()
   167→        } else {
   168→            true
   169→        }
   170→    }
   171→}
