   117→    /// Execute a transform strategy to extract specifications
   118→    fn execute_transform(
   119→        &self,
   120→        transform: &TransformFunction,
   121→        graph: &SpecRepository,
   122→    ) -> Result<Vec<InferredSpecification>, String> {
   123→        match &transform.strategy {
   124→            TransformStrategy::ASTAnalysis { language, extractor_config } => {
   125→                // Execute AST analysis for the specified language
   126→                if language == "rust" {
   127→                    self.execute_rust_ast_analysis(extractor_config, graph)
   128→                } else {
   129→                    Err(format!("Unsupported language: {}", language))
   130→                }
   131→            }
   132→            TransformStrategy::Manual { description: _ } => {
   133→                // Manual transforms don't auto-execute
   134→                Ok(Vec::new())
   135→            }
   136→            _ => {
   137→                // Other strategies not yet implemented
   138→                Ok(Vec::new())
   139→            }
   140→        }
   141→    }
