use super::{RootSpace, Observer, ArtifactSpace};
use crate::formal::UniverseId;

/// Projection: proj_i: Ω → Option β_i
///
/// Composition of observer and extractor:
/// proj_i(x) := Option.bind (obs_i x) extract_i
///
/// This is the formal definition from paper §2.6.
pub struct Projection<O, E> {
    /// Observer: Ω → Option Γ_i
    pub observer: O,

    /// Extractor: Γ_i → Option β_i
    pub extractor: E,

    /// Target layer
    pub target_layer: UniverseId,
}

/// Extractor trait: Γ_i → Option β_i
///
/// Separate from Observer. This is where RustExtractor, APIExtractor, etc. live.
pub trait Extractor<T>: Send + Sync {
    /// Extract layer IR from artifact
    fn extract(&self, artifact: &ArtifactSpace) -> Result<Vec<T>, String>;
}

impl<O, E, T> Projection<O, E>
where
    O: Observer,
    E: Extractor<T>,
{
    /// Execute projection: obs >> extract
    pub fn project(&self, root: &RootSpace) -> Result<Vec<T>, String> {
        // Step 1: Observe artifact from root
        let artifact = self.observer.observe(root, &self.target_layer)
            .ok_or_else(|| format!("No artifact found for layer {}", self.target_layer.as_str()))?;

        // Step 2: Extract IR from artifact
        self.extractor.extract(&artifact)
    }
}
