    39→    #[serde(skip_serializing_if = "Option::is_none")]
    40→    pub metadata: Option<Metadata>,
    41→
    42→    // NEW FIELDS (preferred)
    43→    /// Layer 2: Proof-essential data (constraints, contradictions)
    44→    #[serde(skip_serializing_if = "Option::is_none")]
    45→    pub proof_data: Option<AdmissibleSetProofData>,
    46→
    47→    /// Layer 3: Metadata (organizational info)
