     1→/// Type-safe set of specification IDs
     2→///
     3→/// Internally stores HashSet<String> for serialization compatibility,
     4→/// but enforces type safety through the API.
     5→use serde::{Deserialize, Serialize, Deserializer, Serializer};
     6→use std::collections::HashSet;
     7→use super::SpecId;
     8→use crate::formal::IdError;
     9→
    10→#[derive(Debug, Clone, PartialEq, Eq)]
    11→pub struct SpecSet {
    12→    inner: HashSet<String>,
    13→}
    14→
    15→impl SpecSet {
    16→    /// Create an empty set
    17→    pub fn new() -> Self {
    18→        Self {
    19→            inner: HashSet::new(),
    20→        }
    21→    }
    22→
    23→    /// Insert a specification ID
    24→    pub fn insert(&mut self, id: SpecId) -> bool {
    25→        self.inner.insert(id.as_str().to_string())
    26→    }
    27→
    28→    /// Insert a specification ID from string (validates format)
    29→    pub fn insert_str(&mut self, id_str: String) -> Result<bool, IdError> {
    30→        let id = SpecId::parse(&id_str)?;
    31→        Ok(self.inner.insert(id.as_str().to_string()))
    32→    }
    33→
    34→    /// Check if set contains a specification ID
    35→    pub fn contains(&self, id: &SpecId) -> bool {
    36→        self.inner.contains(id.as_str())
    37→    }
    38→
    39→    /// Check if set contains an ID string (for compatibility)
    40→    pub fn contains_str(&self, id_str: &str) -> bool {
    41→        self.inner.contains(id_str)
    42→    }
    43→
    44→    /// Remove a specification ID
    45→    pub fn remove(&mut self, id: &SpecId) -> bool {
    46→        self.inner.remove(id.as_str())
    47→    }
    48→
    49→    /// Get the number of IDs in the set
    50→    pub fn len(&self) -> usize {
    51→        self.inner.len()
    52→    }
    53→
    54→    /// Check if the set is empty
    55→    pub fn is_empty(&self) -> bool {
    56→        self.inner.is_empty()
    57→    }
    58→
    59→    /// Iterate over IDs as strings (for compatibility)
    60→    pub fn iter_str(&self) -> impl Iterator<Item = &String> {
    61→        self.inner.iter()
    62→    }
    63→
    64→    /// Iterate over parsed SpecIds
    65→    ///
    66→    /// Note: This validates each ID during iteration. IDs that fail validation are skipped.
    67→    pub fn iter(&self) -> impl Iterator<Item = SpecId> + '_ {
    68→        self.inner.iter().filter_map(|s| SpecId::parse(s).ok())
    69→    }
    70→
    71→    /// Validate all IDs in the set
    72→    ///
    73→    /// Returns Err if any ID fails to parse as a valid SpecId.
    74→    pub fn validate(&self) -> Result<(), IdError> {
    75→        for id_str in &self.inner {
    76→            SpecId::parse(id_str)?;
    77→        }
    78→        Ok(())
    79→    }
    80→
    81→    /// Check reference integrity: all IDs in this set exist in the given set
    82→    ///
    83→    /// Returns the list of IDs that don't exist in the reference set.
    84→    pub fn check_integrity(&self, valid_ids: &HashSet<String>) -> Vec<String> {
    85→        self.inner
    86→            .iter()
    87→            .filter(|id| !valid_ids.contains(*id))
    88→            .cloned()
    89→            .collect()
    90→    }
    91→
    92→    /// Get the inner HashSet (for direct access when needed)
    93→    pub fn inner(&self) -> &HashSet<String> {
    94→        &self.inner
    95→    }
    96→
    97→    /// Get mutable reference to inner HashSet
    98→    pub fn inner_mut(&mut self) -> &mut HashSet<String> {
    99→        &mut self.inner
   100→    }
   101→}
   102→
   103→impl Default for SpecSet {
   104→    fn default() -> Self {
   105→        Self::new()
   106→    }
   107→}
   108→
   109→impl From<HashSet<String>> for SpecSet {
   110→    fn from(set: HashSet<String>) -> Self {
   111→        Self { inner: set }
   112→    }
   113→}
   114→
   115→impl From<SpecSet> for HashSet<String> {
   116→    fn from(set: SpecSet) -> Self {
   117→        set.inner
   118→    }
   119→}
   120→
   121→impl Serialize for SpecSet {
   122→    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
   123→    where
   124→        S: Serializer,
   125→    {
   126→        self.inner.serialize(serializer)
   127→    }
   128→}
   129→
   130→impl<'de> Deserialize<'de> for SpecSet {
   131→    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
   132→    where
   133→        D: Deserializer<'de>,
   134→    {
   135→        let inner = HashSet::<String>::deserialize(deserializer)?;
   136→        Ok(Self { inner })
   137→    }
   138→}
