   493→impl UDAFModel {
   494→    /// Construct U0 from projection universes via inverse mappings
   495→    /// U0 = f₀₁⁻¹(U1) ∪ f₀₂⁻¹(U2) ∪ f₀₃⁻¹(U3)
   496→    pub fn construct_u0(
   497→        &mut self,
   498→        graph: &SpecRepository,
   499→        root: &RootSpace,  // NEW: explicit root
   500→    ) -> Result<Vec<InferredSpecification>, String> {
   501→        let mut newly_created_specs = Vec::new();
   502→
   503→        for universe_id in self.universes.keys() {
   504→            if universe_id.layer() == 0 { continue; }
   505→
   506→            let inverse_transform_id = TransformId::inverse(universe_id);
   507→
   508→            if let Some(transform) = self.transforms.get(&inverse_transform_id) {
   509→                let extracted_specs = self.execute_transform(transform, graph, root)?;
   510→                newly_created_specs.extend(extracted_specs);
   511→            }
   512→        }
   513→
   514→        Ok(newly_created_specs)
   515→    }
