                if events.is_empty() { return None; }

                let event_data = serde_json::to_value(events).ok()?;
                Some(ArtifactSpace {
                    content: ArtifactContent::Structured(event_data),
                    kind: ArtifactKind::TestCode,
                    source: format!("trace:{}", self.layer_name),
                })
            }
            _ => None,
        }
    }

    fn artifact_kind(&self) -> ArtifactKind {
        ArtifactKind::TestCode
    }
}
