    }

    /// Content value (text content or file path)
    pub fn content_value(&self) -> Option<&String> {
        self.inner.get("content_value")
    }

    pub fn set_content_value(&mut self, value: String) {
        self.inner.insert("content_value".to_string(), value);
    }

    /// Source reference (where artifact came from)
    pub fn source(&self) -> Option<&String> {
        self.inner.get("source")
    }

    pub fn set_source(&mut self, source: String) {
        self.inner.insert("source".to_string(), source);
    }

    /// Generic getter
    pub fn get(&self, key: &str) -> Option<&String> {
