/// Artifact kind (stored in metadata)
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ArtifactKind {
    RequirementsDoc,
    APISpec,
    SourceCode,
    TestCode,
    TypeDefinitions,
    FormalSpec,
}

impl std::fmt::Display for ArtifactKind {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ArtifactKind::RequirementsDoc => write!(f, "requirements_doc"),
            ArtifactKind::APISpec => write!(f, "api_spec"),
            ArtifactKind::SourceCode => write!(f, "source_code"),
            ArtifactKind::TestCode => write!(f, "test_code"),
            ArtifactKind::TypeDefinitions => write!(f, "type_definitions"),
            ArtifactKind::FormalSpec => write!(f, "formal_spec"),
        }
    }
}

impl ArtifactSpace {
    /// Create new artifact space from text content
    pub fn from_text(text: String, kind: ArtifactKind, source: String) -> Self {
        let mut meta = ArtifactSpaceMetadata::new();
        meta.set_kind(kind);
        meta.set_content_type("text".to_string());
        meta.set_content_value(text);
        meta.set_source(source);

        Self {
            id: ArtifactSpaceId::new(),
            meta: Some(meta),
        }
    }

    /// Create new artifact space from file reference
    pub fn from_file(path: PathBuf, kind: ArtifactKind) -> Self {
        let mut meta = ArtifactSpaceMetadata::new();
        meta.set_kind(kind);
        meta.set_content_type("file_ref".to_string());
        meta.set_content_value(path.to_string_lossy().to_string());
        meta.set_source(path.to_string_lossy().to_string());

        Self {
            id: ArtifactSpaceId::new(),
            meta: Some(meta),
        }
    }

    /// Create new artifact space from structured data
    pub fn from_structured(data: serde_json::Value, kind: ArtifactKind, source: String) -> Self {
        let mut meta = ArtifactSpaceMetadata::new();
        meta.set_kind(kind);
        meta.set_content_type("structured".to_string());
        meta.set_content_value(data.to_string());
        meta.set_source(source);

        Self {
            id: ArtifactSpaceId::new(),
            meta: Some(meta),
        }
    }

    /// Get text content (if available)
    pub fn as_text(&self) -> Result<String, String> {
        let meta = self.meta.as_ref().ok_or("No metadata")?;
        let content_type = meta.content_type().ok_or("No content type")?;
        let content_value = meta.content_value().ok_or("No content value")?;

        match content_type.as_str() {
            "text" => Ok(content_value.clone()),
            "file_ref" => std::fs::read_to_string(content_value)
                .map_err(|e| format!("Failed to read file: {}", e)),
            "structured" => Ok(content_value.clone()),
            _ => Err(format!("Unknown content type: {}", content_type)),
        }
    }
}
